// Package agent provides interfaces and types for integrating with coding agents.
// It abstracts agent-specific behavior (hooks, log parsing, session storage) so that
// the same Strategy implementations can work with any coding agent.
package agent

import (
	"io"
)

// Agent defines the interface for interacting with a coding agent.
// Each agent implementation (Claude Code, Cursor, Aider, etc.) converts its
// native format to the normalized types defined in this package.
//
// The interface is organized into four groups:
//
//   - Identity (5 methods): Name, Type, Description, DetectPresence, ProtectedDirs
//   - Event Mapping (2 methods): HookNames, ParseHookEvent
//   - Transcript Storage (3 methods): ReadTranscript, ChunkTranscript, ReassembleTranscript
//   - Legacy (8 methods): Will be moved to optional interfaces or removed in a future phase
type Agent interface {
	// --- Identity ---

	// Name returns the agent registry key (e.g., "claude-code", "gemini")
	Name() AgentName

	// Type returns the agent type identifier (e.g., "Claude Code", "Gemini CLI")
	// This is stored in metadata and trailers.
	Type() AgentType

	// Description returns a human-readable description for UI
	Description() string

	// DetectPresence checks if this agent is configured in the repository
	DetectPresence() (bool, error)

	// ProtectedDirs returns repo-root-relative directories that should never be
	// modified or deleted during rewind or other destructive operations.
	// Examples: [".claude"] for Claude, [".gemini"] for Gemini.
	ProtectedDirs() []string

	// --- Event Mapping ---

	// HookNames returns the hook verbs this agent supports.
	// These become subcommands under `entire hooks <agent>`.
	// e.g., ["stop", "user-prompt-submit", "session-start", "session-end"]
	HookNames() []string

	// ParseHookEvent translates an agent-native hook into a normalized lifecycle Event.
	// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
	// This is the core contribution surface for new agent implementations.
	ParseHookEvent(hookName string, stdin io.Reader) (*Event, error)

	// --- Transcript Storage ---

	// ReadTranscript reads the raw transcript bytes for a session.
	ReadTranscript(sessionRef string) ([]byte, error)

	// ChunkTranscript splits a transcript into chunks if it exceeds maxSize.
	// Returns a slice of chunks. If the transcript fits in one chunk, returns single-element slice.
	// The chunking is format-aware: JSONL splits at line boundaries, JSON splits message arrays.
	ChunkTranscript(content []byte, maxSize int) ([][]byte, error)

	// ReassembleTranscript combines chunks back into a single transcript.
	// Handles format-specific reassembly (JSONL concatenation, JSON message merging).
	ReassembleTranscript(chunks [][]byte) ([]byte, error)

	// --- Legacy methods (will move to optional interfaces in Phase 4) ---

	// GetHookConfigPath returns path to hook config file (empty if none).
	GetHookConfigPath() string

	// SupportsHooks returns true if agent supports lifecycle hooks.
	SupportsHooks() bool

	// ParseHookInput parses hook callback input from stdin.
	ParseHookInput(hookType HookType, reader io.Reader) (*HookInput, error)

	// GetSessionID extracts session ID from hook input.
	GetSessionID(input *HookInput) string

	// GetSessionDir returns where agent stores session data for this repo.
	GetSessionDir(repoPath string) (string, error)

	// ResolveSessionFile returns the path to the session transcript file.
	ResolveSessionFile(sessionDir, agentSessionID string) string

	// ReadSession reads session data from agent's storage.
	ReadSession(input *HookInput) (*AgentSession, error)

	// WriteSession writes session data for resumption.
	WriteSession(session *AgentSession) error

	// FormatResumeCommand returns command to resume a session.
	FormatResumeCommand(sessionID string) string
}

// HookSupport is implemented by agents with lifecycle hooks.
// This optional interface allows agents like Claude Code and Cursor to
// install and manage hooks that notify Entire of agent events.
type HookSupport interface {
	Agent

	// InstallHooks installs agent-specific hooks.
	// If localDev is true, hooks point to local development build.
	// If force is true, removes existing Entire hooks before installing.
	// Returns the number of hooks installed.
	InstallHooks(localDev bool, force bool) (int, error)

	// UninstallHooks removes installed hooks
	UninstallHooks() error

	// AreHooksInstalled checks if hooks are currently installed
	AreHooksInstalled() bool

	// GetSupportedHooks returns the hook types this agent supports
	GetSupportedHooks() []HookType
}

// HookHandler is implemented by agents that define their own hook vocabulary.
// HookNames() is now part of the core Agent interface.
// This interface is kept for backward compatibility during migration.
type HookHandler interface {
	Agent

	// GetHookNames returns the hook verbs this agent supports.
	GetHookNames() []string
}

// FileWatcher is implemented by agents that use file-based detection.
// Agents like Aider that don't support hooks can use file watching
// to detect session activity.
type FileWatcher interface {
	Agent

	// GetWatchPaths returns paths to watch for session changes
	GetWatchPaths() ([]string, error)

	// OnFileChange handles a detected file change and returns session info
	OnFileChange(path string) (*SessionChange, error)
}

// TranscriptAnalyzer provides format-specific transcript parsing.
// Agents that implement this get richer checkpoints (transcript-derived file lists,
// prompts, summaries). Agents that don't still participate in the checkpoint lifecycle
// via git-status-based file detection and raw transcript storage.
type TranscriptAnalyzer interface {
	Agent

	// GetTranscriptPosition returns the current position (length) of a transcript.
	// For JSONL formats (Claude Code), this is the line count.
	// For JSON formats (Gemini CLI), this is the message count.
	// Returns 0 if the file doesn't exist or is empty.
	GetTranscriptPosition(path string) (int, error)

	// ExtractModifiedFilesFromOffset extracts files modified since a given offset.
	// For JSONL formats (Claude Code), offset is the starting line number.
	// For JSON formats (Gemini CLI), offset is the starting message index.
	// Returns:
	//   - files: list of file paths modified by the agent (from Write/Edit tools)
	//   - currentPosition: the current position (line count or message count)
	//   - error: any error encountered during reading
	ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error)

	// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
	ExtractPrompts(sessionRef string, fromOffset int) ([]string, error)

	// ExtractSummary extracts a summary of the session from the transcript.
	ExtractSummary(sessionRef string) (string, error)
}

// TranscriptPreparer is called before ReadTranscript to handle agent-specific
// flush/sync requirements (e.g., Claude Code's async transcript writing).
// The framework calls PrepareTranscript before ReadTranscript if implemented.
type TranscriptPreparer interface {
	Agent

	// PrepareTranscript ensures the transcript is ready to read.
	// For Claude Code, this waits for the async transcript flush to complete.
	PrepareTranscript(sessionRef string) error
}

// TokenCalculator provides token usage calculation for a session.
// The framework calls this during step save and checkpoint if implemented.
type TokenCalculator interface {
	Agent

	// CalculateTokenUsage computes token usage from the transcript starting at the given offset.
	CalculateTokenUsage(sessionRef string, fromOffset int) (*TokenUsage, error)
}

// SubagentAwareExtractor provides methods for extracting files and tokens including subagents.
// Agents that support spawning subagents (like Claude Code's Task tool) should implement this
// to ensure subagent contributions are included in checkpoints.
type SubagentAwareExtractor interface {
	Agent

	// ExtractAllModifiedFiles extracts files modified by both the main agent and any spawned subagents.
	// The subagentsDir parameter specifies where subagent transcripts are stored.
	// Returns a deduplicated list of all modified file paths.
	ExtractAllModifiedFiles(sessionRef string, fromOffset int, subagentsDir string) ([]string, error)

	// CalculateTotalTokenUsage computes token usage including all spawned subagents.
	// The subagentsDir parameter specifies where subagent transcripts are stored.
	CalculateTotalTokenUsage(sessionRef string, fromOffset int, subagentsDir string) (*TokenUsage, error)
}

package agent

import (
	"fmt"
	"slices"
	"sync"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[AgentName]Factory)
)

// Factory creates a new agent instance
type Factory func() Agent

// Register adds an agent factory to the registry.
// Called from init() in each agent implementation.
func Register(name AgentName, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves an agent by name.
//

func Get(name AgentName) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
	}
	return factory(), nil
}

// List returns all registered agent names in sorted order.
func List() []AgentName {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]AgentName, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// DetectAll returns all agents whose DetectPresence reports true.
// Agents are checked in sorted name order (via List()) for deterministic results.
// Returns an empty slice when no agent is detected.
func DetectAll() []Agent {
	names := List() // sorted, lock-safe

	var detected []Agent
	for _, name := range names {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		if present, err := ag.DetectPresence(); err == nil && present {
			detected = append(detected, ag)
		}
	}
	return detected
}

// Detect attempts to auto-detect which agent is being used.
// Iterates registered agents in sorted name order for deterministic results.
// Returns the first agent whose DetectPresence reports true.
func Detect() (Agent, error) {
	detected := DetectAll()
	if len(detected) == 0 {
		return nil, fmt.Errorf("no agent detected (available: %v)", List())
	}
	return detected[0], nil
}

// AgentName is the registry key type for agents (e.g., "claude-code", "gemini").
//
//nolint:revive // stuttering is intentional - distinguishes from AgentType when both are used
type AgentName string

// AgentType is the display name type stored in metadata/trailers (e.g., "Claude Code", "Gemini CLI").
//
//nolint:revive // stuttering is intentional - distinguishes from AgentName when both are used
type AgentType string

// Agent name constants (registry keys)
const (
	AgentNameClaudeCode AgentName = "claude-code"
	AgentNameGemini     AgentName = "gemini"
)

// Agent type constants (type identifiers stored in metadata/trailers)
const (
	AgentTypeClaudeCode AgentType = "Claude Code"
	AgentTypeGemini     AgentType = "Gemini CLI"
	AgentTypeUnknown    AgentType = "Agent" // Fallback for backwards compatibility
)

// DefaultAgentName is the registry key for the default agent.
const DefaultAgentName AgentName = AgentNameClaudeCode

// GetByAgentType retrieves an agent by its type identifier.
//
// Note: This uses a linear search that instantiates agents until a match is found.
// This is acceptable because:
//   - Agent count is small (~2-20 agents)
//   - Agent factories are lightweight (empty struct allocation)
//   - Called infrequently (commit hooks, rewind, debug commands - not hot paths)
//   - Cost is ~400ns worst case vs milliseconds for I/O operations
//
// Only optimize if agent count exceeds 100 or profiling shows this as a bottleneck.
func GetByAgentType(agentType AgentType) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	for _, factory := range registry {
		ag := factory()
		if ag.Type() == agentType {
			return ag, nil
		}
	}

	return nil, fmt.Errorf("unknown agent type: %s", agentType)
}

// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
func AllProtectedDirs() []string {
	// Copy factories under the lock, then release before calling external code.
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var dirs []string
	for _, factory := range factories {
		for _, d := range factory().ProtectedDirs() {
			if _, ok := seen[d]; !ok {
				seen[d] = struct{}{}
				dirs = append(dirs, d)
			}
		}
	}
	slices.Sort(dirs)
	return dirs
}

// Default returns the default agent.
// Returns nil if the default agent is not registered.
//
//nolint:errcheck // Factory pattern returns interface; error is acceptable to ignore for default
func Default() Agent {
	a, _ := Get(DefaultAgentName)
	return a
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/spf13/cobra"
)

// wingmanLog writes a timestamped log line to stderr. In the detached subprocess,
// stderr is redirected to .entire/logs/wingman.log by the spawner.
func wingmanLog(format string, args ...any) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "%s [wingman] %s\n", time.Now().Format(time.RFC3339), msg)
}

const (
	// wingmanInitialDelay is how long to wait before starting the review,
	// letting the agent turn fully settle.
	wingmanInitialDelay = 10 * time.Second

	// wingmanReviewModel is the Claude model used for reviews.
	wingmanReviewModel = "opus"

	// wingmanGitTimeout is the timeout for git diff operations.
	wingmanGitTimeout = 60 * time.Second

	// wingmanReviewTimeout is the timeout for the claude --print review call.
	wingmanReviewTimeout = 5 * time.Minute

	// wingmanApplyTimeout is the timeout for the claude --continue auto-apply call.
	wingmanApplyTimeout = 15 * time.Minute
)

// wingmanCLIResponse represents the JSON response from the Claude CLI --output-format json.
type wingmanCLIResponse struct {
	Result string `json:"result"`
}

func newWingmanReviewCmd() *cobra.Command {
	return &cobra.Command{
		Use:    "__review",
		Hidden: true,
		Args:   cobra.ExactArgs(1),
		RunE: func(_ *cobra.Command, args []string) error {
			return runWingmanReview(args[0])
		},
	}
}

func runWingmanReview(payloadPath string) error {
	wingmanLog("review process started (pid=%d)", os.Getpid())
	wingmanLog("reading payload from %s", payloadPath)

	// Read payload from file (avoids OS argv limits with large payloads)
	payloadJSON, err := os.ReadFile(payloadPath) //nolint:gosec // path is from our own spawn
	if err != nil {
		wingmanLog("ERROR reading payload: %v", err)
		return fmt.Errorf("failed to read payload file: %w", err)
	}
	// Clean up payload file after reading
	_ = os.Remove(payloadPath)

	var payload WingmanPayload
	if err := json.Unmarshal(payloadJSON, &payload); err != nil {
		wingmanLog("ERROR unmarshaling payload: %v", err)
		return fmt.Errorf("failed to unmarshal payload: %w", err)
	}

	repoRoot := payload.RepoRoot
	if repoRoot == "" {
		wingmanLog("ERROR repo_root is empty in payload")
		return errors.New("repo_root is required in payload")
	}

	totalFiles := len(payload.ModifiedFiles) + len(payload.NewFiles) + len(payload.DeletedFiles)
	wingmanLog("session=%s repo=%s base_commit=%s files=%d",
		payload.SessionID, repoRoot, payload.BaseCommit, totalFiles)

	// Clean up lock file when review completes (regardless of success/failure)
	lockPath := filepath.Join(repoRoot, wingmanLockFile)
	defer func() {
		if err := os.Remove(lockPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			wingmanLog("WARNING: failed to remove lock file: %v", err)
		} else {
			wingmanLog("lock file removed")
		}
	}()

	// Initial delay: let the agent turn fully settle
	wingmanLog("waiting %s for agent turn to settle", wingmanInitialDelay)
	time.Sleep(wingmanInitialDelay)

	// Compute diff using the base commit captured at trigger time
	wingmanLog("computing diff (merge-base with main/master)")
	diffStart := time.Now()
	diff, err := computeDiff(repoRoot)
	if err != nil {
		wingmanLog("ERROR computing diff: %v", err)
		return fmt.Errorf("failed to compute diff: %w", err)
	}

	if strings.TrimSpace(diff) == "" {
		wingmanLog("no changes found in diff, exiting")
		return nil // No changes to review
	}
	wingmanLog("diff computed: %d bytes in %s", len(diff), time.Since(diffStart).Round(time.Millisecond))

	// Build file list for the prompt
	allFiles := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
	for _, f := range payload.ModifiedFiles {
		allFiles = append(allFiles, f+" (modified)")
	}
	for _, f := range payload.NewFiles {
		allFiles = append(allFiles, f+" (new)")
	}
	for _, f := range payload.DeletedFiles {
		allFiles = append(allFiles, f+" (deleted)")
	}
	fileList := strings.Join(allFiles, ", ")

	// Read session context from checkpoint data (best-effort)
	sessionContext := readSessionContext(repoRoot, payload.SessionID)
	if sessionContext != "" {
		wingmanLog("session context loaded: %d bytes", len(sessionContext))
	}

	// Build review prompt
	prompt := buildReviewPrompt(payload.Prompts, payload.CommitMessage, sessionContext, payload.SessionID, fileList, diff)
	wingmanLog("review prompt built: %d bytes", len(prompt))

	// Call Claude CLI for review
	wingmanLog("calling claude CLI (model=%s, timeout=%s)", wingmanReviewModel, wingmanReviewTimeout)
	reviewStart := time.Now()
	reviewText, err := callClaudeForReview(repoRoot, prompt)
	if err != nil {
		wingmanLog("ERROR claude CLI failed after %s: %v", time.Since(reviewStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to get review from Claude: %w", err)
	}
	wingmanLog("review received: %d bytes in %s", len(reviewText), time.Since(reviewStart).Round(time.Millisecond))

	// Write REVIEW.md
	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if err := os.MkdirAll(filepath.Dir(reviewPath), 0o750); err != nil {
		wingmanLog("ERROR creating directory: %v", err)
		return fmt.Errorf("failed to create directory: %w", err)
	}
	//nolint:gosec // G306: review file is not secrets
	if err := os.WriteFile(reviewPath, []byte(reviewText), 0o644); err != nil {
		wingmanLog("ERROR writing REVIEW.md: %v", err)
		return fmt.Errorf("failed to write REVIEW.md: %w", err)
	}
	wingmanLog("REVIEW.md written to %s", reviewPath)

	// Update dedup state — write directly to known path instead of using
	// os.Chdir (which mutates process-wide state).
	allFilePaths := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
	allFilePaths = append(allFilePaths, payload.ModifiedFiles...)
	allFilePaths = append(allFilePaths, payload.NewFiles...)
	allFilePaths = append(allFilePaths, payload.DeletedFiles...)

	saveWingmanStateDirect(repoRoot, &WingmanState{
		SessionID:     payload.SessionID,
		FilesHash:     computeFilesHash(allFilePaths),
		ReviewedAt:    time.Now(),
		ReviewApplied: false,
	})
	wingmanLog("dedup state saved")

	// If any session is live (IDLE/ACTIVE/ACTIVE_COMMITTED), don't auto-apply
	// in the background. The prompt-submit hook will inject REVIEW.md as
	// additionalContext when the user sends their next prompt — this is VISIBLE
	// in their terminal. Only use background auto-apply when no sessions are
	// alive (e.g., user closed all sessions).
	if hasAnyLiveSession(repoRoot) {
		wingmanLog("live session detected, deferring to prompt-submit injection (visible)")
		return nil
	}

	// No live sessions — apply in background as fallback
	wingmanLog("no live sessions, triggering background auto-apply")
	now := time.Now()
	state := loadWingmanStateDirect(repoRoot)
	if state != nil {
		state.ApplyAttemptedAt = &now
		saveWingmanStateDirect(repoRoot, state)
	}

	applyStart := time.Now()
	if err := triggerAutoApply(repoRoot); err != nil {
		wingmanLog("ERROR auto-apply failed after %s: %v", time.Since(applyStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to trigger auto-apply: %w", err)
	}
	wingmanLog("auto-apply completed in %s", time.Since(applyStart).Round(time.Millisecond))

	return nil
}

// computeDiff gets the full branch diff for review. It diffs the current HEAD
// against the merge base with the default branch (main/master), giving the
// reviewer a holistic view of all branch changes rather than just one commit.
func computeDiff(repoRoot string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), wingmanGitTimeout)
	defer cancel()

	// Find the merge base with the default branch for a holistic branch diff.
	mergeBase := findMergeBase(ctx, repoRoot)
	if mergeBase != "" {
		wingmanLog("using merge-base %s for branch diff", mergeBase)
		diff, err := gitDiff(ctx, repoRoot, mergeBase)
		if err == nil && strings.TrimSpace(diff) != "" {
			return diff, nil
		}
		// Fall through to HEAD diff if merge-base diff fails or is empty
	}

	// Fallback: diff uncommitted changes against HEAD
	wingmanLog("falling back to HEAD diff")
	diff, err := gitDiff(ctx, repoRoot, "HEAD")
	if err != nil {
		return "", fmt.Errorf("git diff failed: %w", err)
	}

	// If no uncommitted changes, try the latest commit itself
	if strings.TrimSpace(diff) == "" {
		diff, err = gitDiff(ctx, repoRoot, "HEAD~1", "HEAD")
		if err != nil {
			return "", fmt.Errorf("git diff for latest commit failed: %w", err)
		}
	}

	return diff, nil
}

// findMergeBase returns the merge-base commit between HEAD and the default
// branch (tries main, then master). Returns empty string if not found.
func findMergeBase(ctx context.Context, repoRoot string) string {
	for _, branch := range []string{"main", "master"} {
		cmd := exec.CommandContext(ctx, "git", "merge-base", branch, "HEAD") //nolint:gosec // branch is from hardcoded slice
		cmd.Dir = repoRoot
		out, err := cmd.Output()
		if err == nil {
			return strings.TrimSpace(string(out))
		}
	}
	return ""
}

// gitDiff runs git diff with the given args and returns stdout.
func gitDiff(ctx context.Context, repoRoot string, args ...string) (string, error) {
	fullArgs := append([]string{"diff"}, args...)
	cmd := exec.CommandContext(ctx, "git", fullArgs...) //nolint:gosec // args are from internal logic
	cmd.Dir = repoRoot
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git diff %v: %w (stderr: %s)", args, err, stderr.String())
	}
	return stdout.String(), nil
}

// callClaudeForReview calls the claude CLI to perform the review.
// repoRoot is the repository root so the reviewer can access the full codebase.
func callClaudeForReview(repoRoot, prompt string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), wingmanReviewTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "claude",
		"--print",
		"--output-format", "json",
		"--model", wingmanReviewModel,
		"--setting-sources", "",
		// Grant read-only tool access so the reviewer can inspect source files
		// beyond just the diff. Permission bypass is safe here since tools are
		// restricted to read-only operations.
		"--allowedTools", "Read,Glob,Grep",
		"--permission-mode", "bypassPermissions",
	)

	// Run from repo root so the reviewer can read source files for context.
	// Loop-breaking is handled by --setting-sources "" (disables hooks) and
	// wingmanStripGitEnv (prevents git index pollution).
	cmd.Dir = repoRoot
	cmd.Env = wingmanStripGitEnv(os.Environ())

	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("claude CLI not found: %w", err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return "", fmt.Errorf("claude CLI failed (exit %d): %s", exitErr.ExitCode(), stderr.String())
		}
		return "", fmt.Errorf("failed to run claude CLI: %w", err)
	}

	// Parse the CLI response
	var cliResponse wingmanCLIResponse
	if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
		return "", fmt.Errorf("failed to parse claude CLI response: %w", err)
	}

	return cliResponse.Result, nil
}

// readSessionContext reads the context.md file from the session's checkpoint
// metadata directory. Returns empty string if unavailable.
func readSessionContext(repoRoot, sessionID string) string {
	if sessionID == "" {
		return ""
	}
	contextPath := filepath.Join(repoRoot, ".entire", "metadata", sessionID, "context.md")
	data, err := os.ReadFile(contextPath) //nolint:gosec // path constructed from repoRoot + session ID
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			wingmanLog("WARNING: failed to read session context: %v", err)
		}
		return ""
	}
	return string(data)
}

// staleActiveSessionThreshold is the maximum age of a session state file in an
// ACTIVE phase before it is considered stale (crashed agent) and ignored by
// hasAnyLiveSession. Only applies to ACTIVE/ACTIVE_COMMITTED phases — an IDLE
// session is always considered live regardless of age (user may just be away).
const staleActiveSessionThreshold = 4 * time.Hour

// hasAnyLiveSession checks if any session is in a non-ENDED phase (IDLE,
// ACTIVE, or ACTIVE_COMMITTED). Used to decide whether to defer review
// application to the prompt-submit injection (visible to user) vs background
// auto-apply (invisible).
//
// ACTIVE/ACTIVE_COMMITTED sessions older than staleActiveSessionThreshold are
// skipped as likely orphaned from crashed processes. IDLE sessions are always
// considered live regardless of age.
func hasAnyLiveSession(repoRoot string) bool {
	sessDir := findSessionStateDir(repoRoot)
	if sessDir == "" {
		return false
	}

	entries, err := os.ReadDir(sessDir)
	if err != nil {
		return false
	}

	const maxCheck = 50
	checked := 0
	for _, entry := range entries {
		if checked >= maxCheck {
			wingmanLog("stopping live-session scan after %d entries; assuming live session may exist", checked)
			return true
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".json") {
			continue
		}
		checked++

		sid := strings.TrimSuffix(name, ".json")
		info := readSessionPhaseInfo(sessDir, sid)
		if info.Phase == "" || info.Phase == string(session.PhaseEnded) {
			continue
		}

		// ACTIVE/ACTIVE_COMMITTED sessions that haven't had a real agent
		// interaction in a long time are likely orphaned from crashed agents.
		// Uses LastInteractionTime from JSON (not file modtime) because
		// PostCommit saves all session files on every commit, refreshing
		// modtime even for stale sessions.
		// IDLE sessions are always considered live (user may just be away).
		if session.PhaseFromString(info.Phase).IsActive() {
			if info.LastInteractionTime != nil && time.Since(*info.LastInteractionTime) > staleActiveSessionThreshold {
				wingmanLog("skipping stale active session %s (phase=%s, last_interaction=%s ago)", sid, info.Phase, time.Since(*info.LastInteractionTime).Round(time.Second))
				continue
			}
		}

		wingmanLog("found live session %s (phase=%s)", sid, info.Phase)
		return true
	}

	return false
}

// findSessionStateDir locates the .git/entire-sessions/ directory by
// reading .git to handle both normal repos and worktrees.
func findSessionStateDir(repoRoot string) string {
	gitPath := filepath.Join(repoRoot, ".git")
	info, err := os.Stat(gitPath)
	if err != nil {
		return ""
	}

	var gitDir string
	if info.IsDir() {
		// Normal repo: .git is a directory
		gitDir = gitPath
	} else {
		// Worktree: .git is a file containing "gitdir: <path>"
		data, readErr := os.ReadFile(gitPath) //nolint:gosec // path from repoRoot
		if readErr != nil {
			return ""
		}
		content := strings.TrimSpace(string(data))
		if !strings.HasPrefix(content, "gitdir: ") {
			return ""
		}
		gitDir = strings.TrimPrefix(content, "gitdir: ")
		if !filepath.IsAbs(gitDir) {
			gitDir = filepath.Join(repoRoot, gitDir)
		}
		// For worktrees, session state is in the common dir
		// .git/worktrees/<name> → ../../ is the common .git dir
		commonDir := filepath.Join(gitDir, "..", "..")
		gitDir = filepath.Clean(commonDir)
	}

	sessDir := filepath.Join(gitDir, "entire-sessions")
	if _, statErr := os.Stat(sessDir); statErr != nil {
		return ""
	}
	return sessDir
}

// sessionPhaseInfo holds the subset of session state needed for liveness checks.
type sessionPhaseInfo struct {
	Phase               string
	LastInteractionTime *time.Time
}

func readSessionPhaseInfo(sessDir, sessionID string) sessionPhaseInfo {
	data, err := os.ReadFile(filepath.Join(sessDir, sessionID+".json")) //nolint:gosec // sessDir is from git internals
	if err != nil {
		return sessionPhaseInfo{}
	}
	var partial struct {
		Phase               string     `json:"phase"`
		LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`
	}
	if json.Unmarshal(data, &partial) != nil {
		return sessionPhaseInfo{}
	}
	return sessionPhaseInfo{
		Phase:               partial.Phase,
		LastInteractionTime: partial.LastInteractionTime,
	}
}

// runWingmanApply is the entrypoint for the __apply subcommand, spawned by the
// stop hook when a pending REVIEW.md is detected. It re-checks preconditions
// and triggers claude --continue to apply the review.
func runWingmanApply(repoRoot string) error {
	wingmanLog("apply process started (pid=%d)", os.Getpid())

	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if !fileExists(reviewPath) {
		wingmanLog("no REVIEW.md found at %s, nothing to apply", reviewPath)
		return nil
	}
	wingmanLog("REVIEW.md found at %s", reviewPath)

	// Retry prevention: check if apply was already attempted for this review
	state := loadWingmanStateDirect(repoRoot)
	switch {
	case state == nil:
		wingmanLog("no wingman state found, proceeding without session check")
	case state.ApplyAttemptedAt != nil:
		wingmanLog("apply already attempted at %s, skipping", state.ApplyAttemptedAt.Format(time.RFC3339))
		return nil
	default:
		wingmanLog("wingman state loaded: session=%s", state.SessionID)
	}

	// Re-check session hasn't become active (user may have typed during spawn delay).
	// IDLE and ENDED are safe — only ACTIVE/ACTIVE_COMMITTED should block.
	if state != nil && state.SessionID != "" {
		sessDir := findSessionStateDir(repoRoot)
		if sessDir != "" {
			phaseInfo := readSessionPhaseInfo(sessDir, state.SessionID)
			if phaseInfo.Phase != "" && session.PhaseFromString(phaseInfo.Phase).IsActive() {
				wingmanLog("session is active (phase=%s), aborting (next stop hook will retry)", phaseInfo.Phase)
				return nil
			}
			wingmanLog("session phase=%s, safe to proceed", phaseInfo.Phase)
		}
	}

	// Mark apply as attempted BEFORE triggering
	if state != nil {
		now := time.Now()
		state.ApplyAttemptedAt = &now
		saveWingmanStateDirect(repoRoot, state)
	}

	wingmanLog("triggering auto-apply via claude --continue")
	applyStart := time.Now()
	if err := triggerAutoApply(repoRoot); err != nil {
		wingmanLog("ERROR auto-apply failed after %s: %v", time.Since(applyStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to trigger auto-apply: %w", err)
	}
	wingmanLog("auto-apply completed in %s", time.Since(applyStart).Round(time.Millisecond))

	return nil
}

// triggerAutoApply spawns claude --continue to apply the review suggestions.
func triggerAutoApply(repoRoot string) error {
	ctx, cancel := context.WithTimeout(context.Background(), wingmanApplyTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "claude",
		"--continue",
		"--print",
		"--setting-sources", "",
		// Auto-accept edits so the agent can modify files and delete REVIEW.md
		// without requiring user consent (this runs in a background process).
		"--permission-mode", "acceptEdits",
		wingmanApplyInstruction,
	)
	cmd.Dir = repoRoot
	// Strip GIT_* env vars to prevent hook interference, and set
	// ENTIRE_WINGMAN_APPLY=1 so git hooks (post-commit) know not to
	// trigger another wingman review (prevents infinite recursion).
	env := wingmanStripGitEnv(os.Environ())
	env = append(env, "ENTIRE_WINGMAN_APPLY=1")
	cmd.Env = env

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	return cmd.Run() //nolint:wrapcheck // caller wraps
}

// wingmanStripGitEnv returns a copy of env with all GIT_* variables removed
// and the CLAUDECODE variable unset. GIT_* removal prevents a subprocess from
// discovering or modifying the parent's git repo. CLAUDECODE removal prevents
// the Claude CLI from refusing to start due to nested-session detection.
func wingmanStripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if strings.HasPrefix(e, "GIT_") || strings.HasPrefix(e, "CLAUDECODE=") {
			continue
		}
		filtered = append(filtered, e)
	}
	return filtered
}

// saveWingmanStateDirect writes the wingman state file directly to a known path
// under repoRoot, avoiding os.Chdir (which mutates process-wide state).
func saveWingmanStateDirect(repoRoot string, state *WingmanState) {
	statePath := filepath.Join(repoRoot, wingmanStateFile)
	if err := os.MkdirAll(filepath.Dir(statePath), 0o750); err != nil {
		return
	}
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return
	}
	//nolint:gosec,errcheck // G306: state file is config, not secrets; best-effort write
	_ = os.WriteFile(statePath, data, 0o644)
}

package summarize

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// summarizationPromptTemplate is the prompt used to generate summaries via the Claude CLI.
//
// Security note: The transcript is wrapped in <transcript> tags to provide clear boundary
// markers. This helps contain any potentially malicious content within the transcript
// (e.g., prompt injection attempts in user messages or file contents) by giving the LLM
// a clear structural signal about where the untrusted content begins and ends.
const summarizationPromptTemplate = `Analyze this development session transcript and generate a structured summary.

<transcript>
%s
</transcript>

Return a JSON object with this exact structure:
{
  "intent": "What the user was trying to accomplish (1-2 sentences)",
  "outcome": "What was actually achieved (1-2 sentences)",
  "learnings": {
    "repo": ["Codebase-specific patterns, conventions, or gotchas discovered"],
    "code": [{"path": "file/path.go", "line": 42, "end_line": 56, "finding": "What was learned"}],
    "workflow": ["General development practices or tool usage insights"]
  },
  "friction": ["Problems, blockers, or annoyances encountered"],
  "open_items": ["Tech debt, unfinished work, or things to revisit later"]
}

Guidelines:
- Be concise but specific
- Include line numbers for code learnings when the transcript references specific lines
- Friction should capture both blockers and minor annoyances
- Open items are things intentionally deferred, not failures
- Empty arrays are fine if a category doesn't apply
- Return ONLY the JSON object, no markdown formatting or explanation`

// DefaultModel is the default model used for summarization.
// Sonnet provides a good balance of quality and cost, with 1M context window
// to handle long transcripts without truncation.
const DefaultModel = "sonnet"

// ClaudeGenerator generates summaries using the Claude CLI.
type ClaudeGenerator struct {
	// ClaudePath is the path to the claude CLI executable.
	// If empty, defaults to "claude" (expects it to be in PATH).
	ClaudePath string

	// Model is the Claude model to use for summarization.
	// If empty, defaults to DefaultModel ("sonnet").
	Model string

	// CommandRunner allows injection of the command execution for testing.
	// If nil, uses exec.CommandContext directly.
	CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
}

// claudeCLIResponse represents the JSON response from the Claude CLI.
type claudeCLIResponse struct {
	Result string `json:"result"`
}

// Generate creates a summary from checkpoint data by calling the Claude CLI.
func (g *ClaudeGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	// Format the transcript for the prompt
	transcriptText := FormatCondensedTranscript(input)

	// Build the prompt
	prompt := buildSummarizationPrompt(transcriptText)

	// Execute the Claude CLI
	runner := g.CommandRunner
	if runner == nil {
		runner = exec.CommandContext
	}

	claudePath := g.ClaudePath
	if claudePath == "" {
		claudePath = "claude"
	}

	model := g.Model
	if model == "" {
		model = DefaultModel
	}

	// Use empty --setting-sources to skip all settings (user, project, local).
	// This avoids loading MCP servers, hooks, or other config that could interfere
	// with a simple --print summarization call.
	cmd := runner(ctx, claudePath, "--print", "--output-format", "json", "--model", model, "--setting-sources", "")

	// Fully isolate the subprocess from the user's git repo (ENT-242).
	// Claude Code performs internal git operations (plugin cache, context gathering)
	// that pollute the worktree index with phantom entries from its plugin cache.
	// We must both change the working directory AND strip GIT_* env vars, because
	// git hooks set GIT_DIR which lets Claude Code find the repo regardless of cwd.
	// This also prevents recursive triggering of Entire's own git hooks.
	cmd.Dir = os.TempDir()
	cmd.Env = stripGitEnv(os.Environ())

	// Pass prompt via stdin
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		// Check if the command was not found
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return nil, fmt.Errorf("claude CLI not found: %w", err)
		}

		// Check for exit error
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return nil, fmt.Errorf("claude CLI failed (exit %d): %s", exitErr.ExitCode(), stderr.String())
		}

		return nil, fmt.Errorf("failed to run claude CLI: %w", err)
	}

	// Parse the CLI response
	var cliResponse claudeCLIResponse
	if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
		return nil, fmt.Errorf("failed to parse claude CLI response: %w", err)
	}

	// The result field contains the actual JSON summary
	resultJSON := cliResponse.Result

	// Try to extract JSON if it's wrapped in markdown code blocks
	resultJSON = extractJSONFromMarkdown(resultJSON)

	// Parse the summary from the result
	var summary checkpoint.Summary
	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
		return nil, fmt.Errorf("failed to parse summary JSON: %w (response: %s)", err, resultJSON)
	}

	return &summary, nil
}

// buildSummarizationPrompt creates the prompt for the Claude CLI.
func buildSummarizationPrompt(transcriptText string) string {
	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)
}

// stripGitEnv returns a copy of env with all GIT_* variables removed and the
// CLAUDECODE variable unset. GIT_* removal prevents a subprocess from discovering
// or modifying the parent's git repo. CLAUDECODE removal prevents the Claude CLI
// from refusing to start due to nested-session detection.
func stripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if strings.HasPrefix(e, "GIT_") || strings.HasPrefix(e, "CLAUDECODE=") {
			continue
		}
		filtered = append(filtered, e)
	}
	return filtered
}

// extractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
// If the input is not wrapped in code blocks, it returns the input unchanged.
func extractJSONFromMarkdown(s string) string {
	s = strings.TrimSpace(s)

	// Check for ```json ... ``` blocks
	if strings.HasPrefix(s, "```json") {
		s = strings.TrimPrefix(s, "```json")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	// Check for ``` ... ``` blocks
	if strings.HasPrefix(s, "```") {
		s = strings.TrimPrefix(s, "```")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	return s
}

