313→	return s.strategyOptionString("summarize", "agent")
314→}
315→
316→// SummarizeModel returns the configured model for summarization.
317→// Returns empty string if not configured (callers should default to their own default).
318→func (s *EntireSettings) SummarizeModel() string {
319→	return s.strategyOptionString("summarize", "model")
320→}
321→
322→// strategyOptionString extracts a string value from a nested strategy option.
323→// Returns empty string if the option doesn't exist or isn't a string.
324→func (s *EntireSettings) strategyOptionString(section, key string) string {
325→	if s.StrategyOptions == nil {
326→		return ""
327→	}
328→	sectionOpts, ok := s.StrategyOptions[section].(map[string]any)
329→	if !ok {
330→		return ""
331→	}
332→	val, ok := sectionOpts[key].(string)
333→	if !ok {
334→		return ""
335→	}
336→	return val
337→}
