339→// Save saves the settings to .entire/settings.json.
340→func Save(settings *EntireSettings) error {
341→	return saveToFile(settings, EntireSettingsFile)
342→}
343→
344→// SaveLocal saves the settings to .entire/settings.local.json.
345→func SaveLocal(settings *EntireSettings) error {
346→	return saveToFile(settings, EntireSettingsLocalFile)
347→}
348→
349→// saveToFile saves settings to the specified file path.
350→func saveToFile(settings *EntireSettings, filePath string) error {
351→	// Get absolute path for the file
352→	filePathAbs, err := paths.AbsPath(filePath)
353→	if err != nil {
354→		filePathAbs = filePath // Fallback to relative
355→	}
356→
357→	// Ensure directory exists
358→	dir := filepath.Dir(filePathAbs)
359→	if err := os.MkdirAll(dir, 0o750); err != nil {
360→		return fmt.Errorf("creating settings directory: %w", err)
361→	}
362→
363→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
364→	if err != nil {
365→		return fmt.Errorf("marshaling settings: %w", err)
366→	}
367→
368→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
369→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
370→		return fmt.Errorf("writing settings file: %w", err)
371→	}
372→	return nil
373→}
