167→// GetSessionDir returns the directory where Claude stores session transcripts.
168→func (c *ClaudeCodeAgent) GetSessionDir(repoPath string) (string, error) {
169→	// Check for test environment override
170→	if override := os.Getenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR"); override != "" {
171→		return override, nil
172→	}
173→
174→	homeDir, err := os.UserHomeDir()
175→	if err != nil {
176→		return "", fmt.Errorf("failed to get home directory: %w", err)
177→	}
178→
179→	projectDir := SanitizePathForClaude(repoPath)
