242→// FormatResumeCommand returns the command to resume a Claude Code session.
243→func (c *ClaudeCodeAgent) FormatResumeCommand(sessionID string) string {
244→	return "claude -r " + sessionID
245→}
246→
247→// Session helper methods - work on AgentSession with Claude's native JSONL data
248→
249→// GetLastUserPrompt extracts the last user prompt from the session.
250→// Requires NativeData to be populated (call ReadSession first).
251→func (c *ClaudeCodeAgent) GetLastUserPrompt(session *agent.AgentSession) string {
252→	if session == nil || len(session.NativeData) == 0 {
253→		return ""
254→	}
255→
256→	lines, err := transcript.ParseFromBytes(session.NativeData)
257→	if err != nil {
258→		return ""
259→	}
260→
261→	return ExtractLastUserPrompt(lines)
262→}
