 40→// parseTaskHookInput parses PreToolUse[Task] hook input from reader
 41→func parseTaskHookInput(r io.Reader) (*TaskHookInput, error) {
 42→	data, err := io.ReadAll(r)
 43→	if err != nil {
 44→		return nil, fmt.Errorf("failed to read input: %w", err)
 45→	}
 46→
 47→	if len(data) == 0 {
