 60→func parsePostTaskHookInput(r io.Reader) (*PostTaskHookInput, error) {
 61→	data, err := io.ReadAll(r)
 62→	if err != nil {
 63→		return nil, fmt.Errorf("failed to read input: %w", err)
 64→	}
 65→
 66→	if len(data) == 0 {
