170→// resolveWingmanEnableAgent determines which agent to use for wingman.
171→// If agentFlag is set, validates it. Otherwise, prompts interactively or uses the default.
172→func resolveWingmanEnableAgent(cmd *cobra.Command, agentFlag string) (string, error) {
173→	if agentFlag != "" {
174→		// Validate the agent exists and supports Prompter
175→		ag, err := agent.Get(agent.AgentName(agentFlag))
176→		if err != nil {
177→			return "", fmt.Errorf("unknown agent %q: %w", agentFlag, err)
178→		}
179→		if _, ok := ag.(agent.Prompter); !ok {
180→			return "", fmt.Errorf("agent %q does not support wingman reviews (missing Prompter interface)", agentFlag)
181→		}
182→		return agentFlag, nil
183→	}
184→
185→	// Find agents that implement Prompter
186→	prompterAgents := findPrompterAgents()
187→	if len(prompterAgents) == 0 {
188→		return "", errors.New("no agents support wingman reviews")
189→	}
190→
191→	// Single agent — use it automatically
192→	if len(prompterAgents) == 1 {
193→		name := string(prompterAgents[0].Name())
194→		fmt.Fprintf(cmd.OutOrStdout(), "Using agent: %s\n", prompterAgents[0].Type())
195→		return name, nil
196→	}
197→
198→	// Multiple agents — prompt interactively if possible
199→	if !canPromptInteractively() {
200→		name := string(agent.DefaultAgentName)
201→		fmt.Fprintf(cmd.OutOrStdout(), "Using default agent: %s\n", name)
202→		return name, nil
203→	}
204→
205→	// Build select options
206→	options := make([]huh.Option[string], 0, len(prompterAgents))
207→	for _, ag := range prompterAgents {
208→		label := fmt.Sprintf("%s (%s)", ag.Type(), ag.Name())
209→		if ag.Name() == agent.DefaultAgentName {
210→			label += " (default)"
211→		}
212→		options = append(options, huh.NewOption(label, string(ag.Name())))
213→	}
214→
215→	var selected string
216→	form := NewAccessibleForm(
217→		huh.NewGroup(
218→			huh.NewSelect[string]().
219→				Title("Which agent should wingman use for reviews?").
220→				Options(options...).
221→				Value(&selected),
222→		),
223→	)
224→	if err := form.Run(); err != nil {
225→		return "", fmt.Errorf("agent selection cancelled: %w", err)
226→	}
227→	return selected, nil
228→}
