230→// resolveWingmanEnableModel determines which model to use for wingman.
231→// If modelFlag is set, uses it directly. Otherwise, prompts interactively or uses the default.
232→func resolveWingmanEnableModel(cmd *cobra.Command, modelFlag string) (string, error) {
233→	if modelFlag != "" {
234→		return modelFlag, nil
235→	}
236→
237→	if !canPromptInteractively() {
238→		// Non-interactive: use default silently (resolveWingmanModel() handles fallback at runtime)
239→		return "", nil
240→	}
241→
242→	var selected string
243→	form := NewAccessibleForm(
244→		huh.NewGroup(
245→			huh.NewSelect[string]().
246→				Title("Which model should wingman use?").
247→				Options(
248→					huh.NewOption("opus (default)", "opus"),
249→					huh.NewOption("sonnet", "sonnet"),
250→					huh.NewOption("haiku", "haiku"),
251→				).
252→				Value(&selected),
253→		),
254→	)
255→	if err := form.Run(); err != nil {
256→		return "", fmt.Errorf("model selection cancelled: %w", err)
257→	}
258→	_ = cmd // suppress unused warning in non-interactive path
259→	return selected, nil
260→}
