262→// findPrompterAgents returns all registered agents that implement the Prompter interface.
263→func findPrompterAgents() []agent.Agent {
264→	names := agent.List()
265→	var prompterAgents []agent.Agent
266→	for _, name := range names {
267→		ag, err := agent.Get(name)
268→		if err != nil {
269→			continue
270→		}
271→		if _, ok := ag.(agent.Prompter); ok {
272→			prompterAgents = append(prompterAgents, ag)
273→		}
274→	}
275→	return prompterAgents
276→}
