399→// triggerWingmanReview checks preconditions and spawns the detached review process.
400→func triggerWingmanReview(payload WingmanPayload) {
401→	// Prevent infinite recursion: if we're inside a wingman auto-apply,
402→	// don't trigger another review. The env var is set by triggerAutoApply.
403→	if os.Getenv("ENTIRE_WINGMAN_APPLY") != "" {
404→		return
405→	}
406→
407→	logCtx := logging.WithComponent(context.Background(), "wingman")
408→	repoRoot := payload.RepoRoot
409→
410→	totalFiles := len(payload.ModifiedFiles) + len(payload.NewFiles) + len(payload.DeletedFiles)
411→	logging.Info(logCtx, "wingman trigger evaluating",
412→		slog.String("session_id", payload.SessionID),
413→		slog.Int("file_count", totalFiles),
414→	)
415→
416→	// Check if a pending REVIEW.md already exists for the current session
417→	if shouldSkipPendingReview(repoRoot, payload.SessionID) {
418→		logging.Info(logCtx, "wingman skipped: pending review exists for current session")
419→		fmt.Fprintf(os.Stderr, "[wingman] Pending review exists, skipping\n")
420→		return
421→	}
422→
423→	// Atomic lock file prevents concurrent review spawns. O_CREATE|O_EXCL
424→	// is atomic on all platforms, avoiding the TOCTOU race of Stat+WriteFile.
425→	lockPath := filepath.Join(repoRoot, wingmanLockFile)
426→	if !acquireWingmanLock(lockPath, payload.SessionID) {
427→		logging.Info(logCtx, "wingman skipped: review already in progress")
428→		fmt.Fprintf(os.Stderr, "[wingman] Review in progress, skipping\n")
429→		return
430→	}
431→
432→	// Dedup check: compute hash of sorted file paths
433→	allFiles := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
434→	allFiles = append(allFiles, payload.ModifiedFiles...)
435→	allFiles = append(allFiles, payload.NewFiles...)
436→	allFiles = append(allFiles, payload.DeletedFiles...)
437→	filesHash := computeFilesHash(allFiles)
438→
439→	state, _ := loadWingmanState() //nolint:errcheck // best-effort dedup
440→	if state != nil && state.FilesHash == filesHash && state.SessionID == payload.SessionID {
441→		logging.Info(logCtx, "wingman skipped: dedup hash match",
442→			slog.String("files_hash", filesHash[:12]),
443→		)
444→		fmt.Fprintf(os.Stderr, "[wingman] Already reviewed these changes, skipping\n")
445→		return
446→	}
447→
448→	// Capture HEAD at trigger time so the detached review diffs against
449→	// the correct commit even if HEAD moves during the initial delay.
450→	payload.BaseCommit = resolveHEAD(repoRoot)
451→	logging.Debug(logCtx, "wingman captured base commit",
452→		slog.String("base_commit", payload.BaseCommit),
453→	)
454→
455→	// Write payload to a temp file instead of passing as a CLI argument,
456→	// which can exceed OS argv limits (~128KB Linux, ~256KB macOS) with
457→	// many files or long prompts.
458→	payloadJSON, err := json.Marshal(payload)
459→	if err != nil {
460→		logging.Error(logCtx, "wingman failed to marshal payload", slog.Any("error", err))
461→		fmt.Fprintf(os.Stderr, "[wingman] Failed to marshal payload: %v\n", err)
462→		_ = os.Remove(lockPath)
463→		return
464→	}
465→	payloadPath := filepath.Join(repoRoot, ".entire", "wingman-payload.json")
466→	//nolint:gosec // G306: payload file is not secrets
467→	if err := os.WriteFile(payloadPath, payloadJSON, 0o644); err != nil {
468→		logging.Error(logCtx, "wingman failed to write payload file", slog.Any("error", err))
469→		fmt.Fprintf(os.Stderr, "[wingman] Failed to write payload file: %v\n", err)
470→		_ = os.Remove(lockPath)
471→		return
472→	}
473→
474→	// Spawn detached review process with path to payload file
475→	spawnDetachedWingmanReview(repoRoot, payloadPath)
476→	logging.Info(logCtx, "wingman review spawned",
477→		slog.String("session_id", payload.SessionID),
478→		slog.String("base_commit", payload.BaseCommit),
479→		slog.Int("file_count", totalFiles),
480→	)
481→	fmt.Fprintf(os.Stderr, "[wingman] Review starting in background...\n")
482→}
483→
484→// triggerWingmanFromCommit builds a wingman payload from the HEAD commit and
485→// triggers a review. Used by the git post-commit hook for manual-commit strategy
486→// where files are committed by the user (not by SaveChanges).
487→func triggerWingmanFromCommit() {
488→	// Prevent infinite recursion: skip if inside wingman auto-apply
489→	if os.Getenv("ENTIRE_WINGMAN_APPLY") != "" {
490→		return
491→	}
492→	if !settings.IsWingmanEnabled() {
493→		return
494→	}
495→
496→	repoRoot, err := paths.RepoRoot()
497→	if err != nil {
498→		return
499→	}
500→
501→	head := resolveHEAD(repoRoot)
502→	if head == "" {
503→		return
504→	}
505→
506→	// Get changed files from the commit
507→	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
508→	defer cancel()
509→	//nolint:gosec // G204: head is from git rev-parse, not user input
510→	cmd := exec.CommandContext(ctx, "git", "diff-tree", "--no-commit-id", "--name-status", "-r", head)
511→	cmd.Dir = repoRoot
512→	out, err := cmd.Output()
513→	if err != nil || len(out) == 0 {
514→		return
515→	}
516→
517→	var modified, newFiles, deleted []string
518→	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
519→		if len(line) < 3 {
520→			continue
521→		}
522→		status := line[0]
523→		file := strings.TrimSpace(line[1:])
524→		switch status {
525→		case 'M':
526→			modified = append(modified, file)
527→		case 'A':
528→			newFiles = append(newFiles, file)
529→		case 'D':
530→			deleted = append(deleted, file)
531→		}
532→	}
533→
534→	if len(modified)+len(newFiles)+len(deleted) == 0 {
535→		return
536→	}
537→
538→	// Get commit message
539→	//nolint:gosec // G204: head is from git rev-parse, not user input
540→	msgCmd := exec.CommandContext(ctx, "git", "log", "-1", "--format=%B", head)
541→	msgCmd.Dir = repoRoot
542→	msgOut, _ := msgCmd.Output() //nolint:errcheck // best-effort commit message
543→	commitMessage := strings.TrimSpace(string(msgOut))
544→
545→	sessionID := strategy.FindMostRecentSession()
546→
547→	triggerWingmanReview(WingmanPayload{
548→		SessionID:     sessionID,
549→		RepoRoot:      repoRoot,
550→		ModifiedFiles: modified,
551→		NewFiles:      newFiles,
552→		DeletedFiles:  deleted,
553→		CommitMessage: commitMessage,
554→	})
555→}
556→
557→// staleLockThreshold is how old a lock file can be before we consider it stale
558→// (e.g., the detached process was SIGKILLed and the defer never ran).
559→const staleLockThreshold = 30 * time.Minute
560→
561→// acquireWingmanLock atomically creates the lock file. Returns true if acquired.
562→// If the lock already exists but is older than staleLockThreshold, it is removed
563→// and re-acquired (handles crashed detached processes).
564→func acquireWingmanLock(lockPath, sessionID string) bool {
565→	//nolint:gosec // G304: lockPath is constructed from repoRoot + constant
566→	f, err := os.OpenFile(lockPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
567→	if err != nil {
568→		if !errors.Is(err, os.ErrExist) {
569→			fmt.Fprintf(os.Stderr, "[wingman] Failed to create lock: %v\n", err)
570→			return false
571→		}
572→		// Lock exists — check if it's stale
573→		info, statErr := os.Stat(lockPath)
574→		if statErr != nil || time.Since(info.ModTime()) <= staleLockThreshold {
575→			fmt.Fprintf(os.Stderr, "[wingman] Review already in progress, skipping\n")
576→			return false
577→		}
578→		fmt.Fprintf(os.Stderr, "[wingman] Removing stale lock (age: %s)\n",
579→			time.Since(info.ModTime()).Round(time.Second))
580→		_ = os.Remove(lockPath)
581→		// Retry the atomic create
582→		//nolint:gosec // G304: lockPath is constructed from repoRoot + constant
583→		f, err = os.OpenFile(lockPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
584→		if err != nil {
585→			fmt.Fprintf(os.Stderr, "[wingman] Failed to create lock after stale removal: %v\n", err)
586→			return false
587→		}
588→	}
589→	_, _ = f.WriteString(sessionID) //nolint:errcheck // best-effort session ID write
590→	_ = f.Close()
591→	return true
592→}
593→
594→// resolveHEAD returns the current HEAD commit hash, or empty string on error.
595→func resolveHEAD(repoRoot string) string {
596→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
597→	defer cancel()
598→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "HEAD")
599→	cmd.Dir = repoRoot
600→	out, err := cmd.Output()
601→	if err != nil {
602→		return ""
603→	}
604→	return strings.TrimSpace(string(out))
605→}
