688→// shouldSkipPendingReview checks whether a pending REVIEW.md should prevent
689→// a new review from being triggered. It cleans up stale/orphaned reviews.
690→//
691→// Returns true only when REVIEW.md exists AND belongs to the current session
692→// AND is younger than wingmanStaleReviewTTL.
693→func shouldSkipPendingReview(repoRoot, currentSessionID string) bool {
694→	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
695→	if _, err := os.Stat(reviewPath); err != nil {
696→		return false // No REVIEW.md, don't skip
697→	}
698→
699→	// REVIEW.md exists — check state to determine if it's current or stale
700→	state := loadWingmanStateDirect(repoRoot)
701→	if state == nil {
702→		// Orphan: REVIEW.md without state file — clean up
703→		_ = os.Remove(reviewPath)
704→		return false
705→	}
706→
707→	if state.SessionID != currentSessionID {
708→		// Different session — stale review, clean up
709→		_ = os.Remove(reviewPath)
710→		return false
711→	}
712→
713→	if time.Since(state.ReviewedAt) > wingmanStaleReviewTTL {
714→		// Same session but too old — clean up
715→		_ = os.Remove(reviewPath)
716→		return false
717→	}
718→
719→	return true // Current session, fresh review — skip
720→}
