505→// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
506→func handleLifecycleSubagentEnd(ag agent.Agent, event *agent.Event) error {
507→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
508→	logging.Info(logCtx, "subagent-end",
509→		slog.String("event", event.Type.String()),
510→		slog.String("session_id", event.SessionID),
511→		slog.String("tool_use_id", event.ToolUseID),
512→		slog.String("subagent_id", event.SubagentID),
513→	)
514→
515→	// Extract subagent type and description from tool input
516→	subagentType, taskDescription := ParseSubagentTypeAndDescription(event.ToolInput)
517→
518→	// Determine subagent transcript path
519→	transcriptDir := filepath.Dir(event.SessionRef)
520→	var subagentTranscriptPath string
521→	if event.SubagentID != "" {
522→		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
523→		if !fileExists(subagentTranscriptPath) {
524→			subagentTranscriptPath = ""
525→		}
526→	}
527→
528→	// Log context
529→	fmt.Fprintf(os.Stderr, "[entire] Subagent completed\n")
530→	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
531→	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
532→	if event.SubagentID != "" {
533→		fmt.Fprintf(os.Stderr, "  Agent ID: %s\n", event.SubagentID)
534→	}
535→	if subagentTranscriptPath != "" {
536→		fmt.Fprintf(os.Stderr, "  Subagent Transcript: %s\n", subagentTranscriptPath)
537→	}
538→
539→	// Extract modified files from subagent transcript
540→	var modifiedFiles []string
541→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
542→		transcriptToScan := event.SessionRef
543→		if subagentTranscriptPath != "" {
544→			transcriptToScan = subagentTranscriptPath
545→		}
546→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
547→			fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files from subagent: %v\n", fileErr)
548→		} else {
549→			modifiedFiles = files
550→		}
551→	}
552→
553→	// Load pre-task state and detect file changes
554→	preState, err := LoadPreTaskState(event.ToolUseID)
555→	if err != nil {
556→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
557→	}
558→	var preUntrackedFiles []string
559→	if preState != nil {
560→		preUntrackedFiles = preState.PreUntrackedFiles()
561→	}
562→	changes, err := DetectFileChanges(preUntrackedFiles)
563→	if err != nil {
564→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
565→	}
566→
567→	// Get repo root and normalize paths
568→	repoRoot, err := paths.RepoRoot()
569→	if err != nil {
570→		return fmt.Errorf("failed to get repo root: %w", err)
571→	}
572→
573→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
574→	var relNewFiles, relDeletedFiles []string
575→	if changes != nil {
576→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
577→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
578→	}
579→
580→	// If no changes, skip
581→	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
582→		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
583→		_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
584→		return nil
585→	}
586→
587→	// Find checkpoint UUID from main transcript (best-effort)
588→	var checkpointUUID string
589→	// Use the existing CLI-level checkpoint UUID finder
590→	mainLines, _, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
591→	if mainLines != nil {
592→		checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
593→	}
594→
595→	// Get git author
596→	author, err := GetGitAuthor()
597→	if err != nil {
598→		return fmt.Errorf("failed to get git author: %w", err)
599→	}
600→
601→	// Build task checkpoint context
602→	strat := GetStrategy()
603→	agentType := ag.Type()
604→
605→	ctx := strategy.TaskStepContext{
606→		SessionID:              event.SessionID,
607→		ToolUseID:              event.ToolUseID,
608→		AgentID:                event.SubagentID,
609→		ModifiedFiles:          relModifiedFiles,
610→		NewFiles:               relNewFiles,
611→		DeletedFiles:           relDeletedFiles,
612→		TranscriptPath:         event.SessionRef,
613→		SubagentTranscriptPath: subagentTranscriptPath,
614→		CheckpointUUID:         checkpointUUID,
615→		AuthorName:             author.Name,
616→		AuthorEmail:            author.Email,
617→		SubagentType:           subagentType,
618→		TaskDescription:        taskDescription,
619→		AgentType:              agentType,
620→	}
621→
622→	if err := strat.SaveTaskStep(ctx); err != nil {
623→		return fmt.Errorf("failed to save task step: %w", err)
624→	}
625→
626→	_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
627→	return nil
628→}
