160→// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
161→// detects file changes, saves step + checkpoint, transitions phase.
162→//
163→//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
164→func handleLifecycleTurnEnd(ag agent.Agent, event *agent.Event) error {
165→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
166→	logging.Info(logCtx, "turn-end",
167→		slog.String("event", event.Type.String()),
168→		slog.String("session_id", event.SessionID),
169→		slog.String("session_ref", event.SessionRef),
170→	)
171→
172→	sessionID := event.SessionID
173→	if sessionID == "" {
174→		sessionID = unknownSessionID
175→	}
176→
177→	transcriptRef := event.SessionRef
178→	if transcriptRef == "" {
179→		return errors.New("transcript file not specified")
180→	}
181→	if !fileExists(transcriptRef) {
182→		return fmt.Errorf("transcript file not found: %s", transcriptRef)
183→	}
184→
185→	// Early check: bail out quickly if the repo has no commits yet.
186→	if repo, err := strategy.OpenRepository(); err == nil && strategy.IsEmptyRepository(repo) {
187→		fmt.Fprintln(os.Stderr, "Entire: skipping checkpoint. Will activate after first commit.")
188→		return NewSilentError(strategy.ErrEmptyRepository)
189→	}
190→
191→	// Create session metadata directory
192→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
193→	sessionDirAbs, err := paths.AbsPath(sessionDir)
194→	if err != nil {
195→		sessionDirAbs = sessionDir
196→	}
197→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
198→		return fmt.Errorf("failed to create session directory: %w", err)
199→	}
200→
201→	// If agent implements TranscriptPreparer, wait for transcript to be ready
202→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
203→		if err := preparer.PrepareTranscript(transcriptRef); err != nil {
204→			fmt.Fprintf(os.Stderr, "Warning: failed to prepare transcript: %v\n", err)
205→		}
206→	}
207→
208→	// Copy transcript to session directory
209→	transcriptData, err := ag.ReadTranscript(transcriptRef)
210→	if err != nil {
211→		return fmt.Errorf("failed to read transcript: %w", err)
212→	}
213→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
214→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
215→		return fmt.Errorf("failed to write transcript: %w", err)
216→	}
217→	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)
218→
219→	// Load pre-prompt state (captured on TurnStart)
220→	preState, err := LoadPrePromptState(sessionID)
221→	if err != nil {
222→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
223→	}
224→
225→	// Determine transcript offset
226→	transcriptOffset := resolveTranscriptOffset(preState, sessionID)
227→
228→	// Extract metadata via agent interface (prompts, summary, modified files)
229→	var allPrompts []string
230→	var summary string
231→	var modifiedFiles []string
232→	var newTranscriptPosition int
233→
234→	// Compute subagents directory for agents that support subagent extraction.
235→	// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
236→	subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
237→
238→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
239→		// Extract prompts
240→		if prompts, promptErr := analyzer.ExtractPrompts(transcriptRef, transcriptOffset); promptErr != nil {
241→			fmt.Fprintf(os.Stderr, "Warning: failed to extract prompts: %v\n", promptErr)
242→		} else {
243→			allPrompts = prompts
244→		}
245→
246→		// Extract summary
247→		if s, sumErr := analyzer.ExtractSummary(transcriptRef); sumErr != nil {
248→			fmt.Fprintf(os.Stderr, "Warning: failed to extract summary: %v\n", sumErr)
249→		} else {
250→			summary = s
251→		}
252→
253→		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
254→		if subagentExtractor, subOk := ag.(agent.SubagentAwareExtractor); subOk {
255→			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptRef, transcriptOffset, subagentsDir); fileErr != nil {
256→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files (with subagents): %v\n", fileErr)
257→			} else {
258→				modifiedFiles = files
259→			}
260→			// Get position from basic analyzer
261→			if _, pos, posErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); posErr == nil {
262→				newTranscriptPosition = pos
263→			}
264→		} else {
265→			// Fall back to basic extraction (main transcript only)
266→			if files, pos, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
267→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files: %v\n", fileErr)
268→			} else {
269→				modifiedFiles = files
270→				newTranscriptPosition = pos
271→			}
272→		}
273→	}
274→
275→	// Write prompts file
276→	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
277→	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
278→	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
279→		return fmt.Errorf("failed to write prompt file: %w", err)
280→	}
281→	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)
282→
283→	// Write summary file
284→	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
285→	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
286→		return fmt.Errorf("failed to write summary file: %w", err)
287→	}
288→	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)
289→
290→	// Generate commit message from last prompt
291→	lastPrompt := ""
292→	if len(allPrompts) > 0 {
293→		lastPrompt = allPrompts[len(allPrompts)-1]
294→	}
295→	commitMessage := generateCommitMessage(lastPrompt)
296→	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)
297→
298→	// Get repo root for path normalization
299→	repoRoot, err := paths.RepoRoot()
300→	if err != nil {
301→		return fmt.Errorf("failed to get repo root: %w", err)
302→	}
303→
304→	var preUntrackedFiles []string
305→	if preState != nil {
306→		fmt.Fprintf(os.Stderr, "Pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
307→		preUntrackedFiles = preState.PreUntrackedFiles()
308→	}
309→
310→	// Detect file changes via git status
311→	changes, err := DetectFileChanges(preUntrackedFiles)
312→	if err != nil {
313→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
314→	}
315→
316→	// Filter and normalize all paths
317→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
318→	var relNewFiles, relDeletedFiles []string
319→	if changes != nil {
320→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
321→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
322→	}
323→
324→	// Filter transcript-extracted files to exclude files already committed to HEAD.
325→	// When an agent commits files mid-turn, those files are condensed by PostCommit
326→	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
327→	// if it exists in HEAD with the same content as the working tree.
328→	relModifiedFiles = filterToUncommittedFiles(relModifiedFiles, repoRoot)
329→
330→	// Check if there are any changes
331→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
332→	if totalChanges == 0 {
333→		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
334→		fmt.Fprintf(os.Stderr, "Skipping commit\n")
335→		transitionSessionTurnEnd(sessionID)
336→		// Auto-apply pending wingman review even when no file changes this turn
337→		handleWingmanTurnEnd(sessionID, 0, nil, nil, nil, nil, "")
338→		if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
339→			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
340→		}
341→		return nil
342→	}
343→
344→	// Log file changes
345→	logFileChanges(relModifiedFiles, relNewFiles, relDeletedFiles)
346→
347→	// Create context file
348→	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
349→	if err := createContextFile(contextFile, commitMessage, sessionID, allPrompts, summary); err != nil {
350→		return fmt.Errorf("failed to create context file: %w", err)
351→	}
352→	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)
353→
354→	// Get git author
355→	author, err := GetGitAuthor()
356→	if err != nil {
357→		return fmt.Errorf("failed to get git author: %w", err)
358→	}
359→
360→	// Get strategy and agent type
361→	strat := GetStrategy()
362→	agentType := ag.Type()
363→
364→	// Get transcript position/identifier from pre-prompt state
365→	var transcriptIdentifierAtStart string
366→	var transcriptLinesAtStart int
367→	if preState != nil {
368→		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
369→		transcriptLinesAtStart = preState.TranscriptOffset
370→	}
371→
372→	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
373→	var tokenUsage *agent.TokenUsage
374→	if subagentExtractor, ok := ag.(agent.SubagentAwareExtractor); ok {
375→		usage, tokenErr := subagentExtractor.CalculateTotalTokenUsage(transcriptRef, transcriptLinesAtStart, subagentsDir)
376→		if tokenErr != nil {
377→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage (with subagents): %v\n", tokenErr)
378→		} else {
379→			tokenUsage = usage
380→		}
381→	} else if calculator, ok := ag.(agent.TokenCalculator); ok {
382→		// Fall back to basic token calculation (main transcript only)
383→		usage, tokenErr := calculator.CalculateTokenUsage(transcriptRef, transcriptLinesAtStart)
384→		if tokenErr != nil {
385→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
386→		} else {
387→			tokenUsage = usage
388→		}
389→	}
390→
391→	// Build fully-populated step context and delegate to strategy
392→	ctx := strategy.StepContext{
393→		SessionID:                sessionID,
394→		ModifiedFiles:            relModifiedFiles,
395→		NewFiles:                 relNewFiles,
396→		DeletedFiles:             relDeletedFiles,
397→		MetadataDir:              sessionDir,
398→		MetadataDirAbs:           sessionDirAbs,
399→		CommitMessage:            commitMessage,
400→		TranscriptPath:           transcriptRef,
401→		AuthorName:               author.Name,
402→		AuthorEmail:              author.Email,
403→		AgentType:                agentType,
404→		StepTranscriptIdentifier: transcriptIdentifierAtStart,
405→		StepTranscriptStart:      transcriptLinesAtStart,
406→		TokenUsage:               tokenUsage,
407→	}
408→
409→	if err := strat.SaveStep(ctx); err != nil {
410→		return fmt.Errorf("failed to save step: %w", err)
411→	}
412→
413→	// Update session state transcript position for auto-commit strategy
414→	if strat.Name() == strategy.StrategyNameAutoCommit && newTranscriptPosition > 0 {
415→		updateAutoCommitTranscriptPosition(sessionID, newTranscriptPosition)
416→	}
417→
418→	// Transition session phase and cleanup
419→	transitionSessionTurnEnd(sessionID)
420→
421→	// Wingman: trigger review (auto-commit), auto-apply, and stop notification
422→	handleWingmanTurnEnd(sessionID, totalChanges, relModifiedFiles, relNewFiles, relDeletedFiles, allPrompts, commitMessage)
423→
424→	if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
425→		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
426→	}
427→
428→	return nil
429→}
