766→// logFileChanges logs the files modified, created, and deleted during a session.
767→func logFileChanges(modified, newFiles, deleted []string) {
768→	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(modified))
769→	for _, file := range modified {
770→		fmt.Fprintf(os.Stderr, "  - %s\n", file)
771→	}
772→	if len(newFiles) > 0 {
773→		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(newFiles))
774→		for _, file := range newFiles {
775→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
776→		}
777→	}
778→	if len(deleted) > 0 {
779→		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(deleted))
780→		for _, file := range deleted {
781→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
782→		}
783→	}
784→}
