  1→// lifecycle.go implements the generic lifecycle event dispatcher.
  2→// It routes normalized events from any agent to the appropriate framework actions.
  3→//
  4→// The dispatcher inverts the current flow from "agent handler calls framework functions"
  5→// to "framework dispatcher calls agent methods." Agents are passive data providers;
  6→// the dispatcher handles all orchestration: state transitions, strategy calls,
  7→// file change detection, metadata generation.
  8→package cli
  9→
 10→import (
 11→	"context"
 12→	"errors"
 13→	"fmt"
 14→	"log/slog"
 15→	"os"
 16→	"path/filepath"
 17→	"strings"
 18→	"time"
 19→
 20→	"github.com/entireio/cli/cmd/entire/cli/agent"
 21→	"github.com/entireio/cli/cmd/entire/cli/logging"
 22→	"github.com/entireio/cli/cmd/entire/cli/paths"
 23→	"github.com/entireio/cli/cmd/entire/cli/session"
 24→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 25→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 26→	"github.com/entireio/cli/cmd/entire/cli/validation"
 27→)
 28→
 29→// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
 30→// Returns nil if the event was handled successfully.
 31→func DispatchLifecycleEvent(ag agent.Agent, event *agent.Event) error {
 32→	if ag == nil {
 33→		return errors.New("agent cannot be nil")
 34→	}
 35→	if event == nil {
 36→		return errors.New("event cannot be nil")
 37→	}
 38→
 39→	switch event.Type {
 40→	case agent.SessionStart:
 41→		return handleLifecycleSessionStart(ag, event)
 42→	case agent.TurnStart:
 43→		return handleLifecycleTurnStart(ag, event)
 44→	case agent.TurnEnd:
 45→		return handleLifecycleTurnEnd(ag, event)
 46→	case agent.Compaction:
 47→		return handleLifecycleCompaction(ag, event)
 48→	case agent.SessionEnd:
 49→		return handleLifecycleSessionEnd(ag, event)
 50→	case agent.SubagentStart:
 51→		return handleLifecycleSubagentStart(ag, event)
 52→	case agent.SubagentEnd:
 53→		return handleLifecycleSubagentEnd(ag, event)
 54→	default:
 55→		return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
 56→	}
 57→}
 58→
 59→// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
 60→// fires state machine transition.
 61→func handleLifecycleSessionStart(ag agent.Agent, event *agent.Event) error {
 62→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
 63→	logging.Info(logCtx, "session-start",
 64→		slog.String("event", event.Type.String()),
 65→		slog.String("session_id", event.SessionID),
 66→		slog.String("session_ref", event.SessionRef),
 67→	)
 68→
 69→	if event.SessionID == "" {
 70→		return fmt.Errorf("no session_id in %s event", event.Type)
 71→	}
 72→	if err := validation.ValidateSessionID(event.SessionID); err != nil {
 73→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
 74→	}
 75→
 76→	// Build informational message
 77→	message := "\n\nPowered by Entire:\n  This conversation will be linked to your next commit."
 78→
 79→	// Append wingman status if enabled
 80→	message = appendWingmanSessionStartStatus(message)
 81→
 82→	// Check for concurrent sessions and append count if any
 83→	strat := GetStrategy()
 84→	if concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker); ok {
 85→		if count, err := concurrentChecker.CountOtherActiveSessionsWithCheckpoints(event.SessionID); err == nil && count > 0 {
 86→			message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
 87→		}
 88→	}
 89→
 90→	// Output informational message
 91→	if event.ResponseMessage != "" {
 92→		message = event.ResponseMessage
 93→	}
 94→	if err := outputHookResponse(message); err != nil {
 95→		return err
 96→	}
 97→
 98→	// Fire EventSessionStart for the current session (if state exists).
 99→	if state, loadErr := strategy.LoadSessionState(event.SessionID); loadErr != nil {
100→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state on start: %v\n", loadErr)
101→	} else if state != nil {
102→		if transErr := strategy.TransitionAndLog(state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
103→			fmt.Fprintf(os.Stderr, "Warning: session start transition failed: %v\n", transErr)
104→		}
105→		if saveErr := strategy.SaveSessionState(state); saveErr != nil {
106→			fmt.Fprintf(os.Stderr, "Warning: failed to update session state on start: %v\n", saveErr)
107→		}
108→	}
109→
110→	return nil
111→}
112→
113→// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
114→// ensures strategy setup, initializes session.
115→func handleLifecycleTurnStart(ag agent.Agent, event *agent.Event) error {
116→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
117→	logging.Info(logCtx, "turn-start",
118→		slog.String("event", event.Type.String()),
119→		slog.String("session_id", event.SessionID),
120→		slog.String("session_ref", event.SessionRef),
121→	)
122→
123→	sessionID := event.SessionID
124→	if sessionID == "" {
125→		return fmt.Errorf("no session_id in %s event", event.Type)
126→	}
127→	if err := validation.ValidateSessionID(sessionID); err != nil {
128→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
129→	}
130→
131→	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
132→	if err := CapturePrePromptState(ag, sessionID, event.SessionRef); err != nil {
133→		return err
134→	}
135→
136→	// If a wingman review is pending, inject it as additionalContext so the
137→	// agent addresses it BEFORE the user's request. Must return early to
138→	// avoid corrupting the JSON stdout with additional output.
139→	if handleWingmanTurnStart(sessionID) {
140→		return nil
141→	}
142→
143→	// Ensure strategy setup and initialize session
144→	strat := GetStrategy()
145→
146→	if err := strat.EnsureSetup(); err != nil {
147→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
148→	}
149→
150→	if initializer, ok := strat.(strategy.SessionInitializer); ok {
151→		agentType := ag.Type()
152→		if err := initializer.InitializeSession(sessionID, agentType, event.SessionRef, event.Prompt); err != nil {
153→			fmt.Fprintf(os.Stderr, "Warning: failed to initialize session state: %v\n", err)
154→		}
155→	}
156→
157→	return nil
158→}
159→
160→// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
161→// detects file changes, saves step + checkpoint, transitions phase.
162→//
163→//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
164→func handleLifecycleTurnEnd(ag agent.Agent, event *agent.Event) error {
165→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
166→	logging.Info(logCtx, "turn-end",
167→		slog.String("event", event.Type.String()),
168→		slog.String("session_id", event.SessionID),
169→		slog.String("session_ref", event.SessionRef),
170→	)
171→
172→	sessionID := event.SessionID
173→	if sessionID == "" {
174→		sessionID = unknownSessionID
175→	}
176→
177→	transcriptRef := event.SessionRef
178→	if transcriptRef == "" {
179→		return errors.New("transcript file not specified")
180→	}
181→	if !fileExists(transcriptRef) {
182→		return fmt.Errorf("transcript file not found: %s", transcriptRef)
183→	}
184→
185→	// Early check: bail out quickly if the repo has no commits yet.
186→	if repo, err := strategy.OpenRepository(); err == nil && strategy.IsEmptyRepository(repo) {
187→		fmt.Fprintln(os.Stderr, "Entire: skipping checkpoint. Will activate after first commit.")
188→		return NewSilentError(strategy.ErrEmptyRepository)
189→	}
190→
191→	// Create session metadata directory
192→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
193→	sessionDirAbs, err := paths.AbsPath(sessionDir)
194→	if err != nil {
195→		sessionDirAbs = sessionDir
196→	}
197→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
198→		return fmt.Errorf("failed to create session directory: %w", err)
199→	}
200→
201→	// If agent implements TranscriptPreparer, wait for transcript to be ready
202→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
203→		if err := preparer.PrepareTranscript(transcriptRef); err != nil {
204→			fmt.Fprintf(os.Stderr, "Warning: failed to prepare transcript: %v\n", err)
205→		}
206→	}
207→
208→	// Copy transcript to session directory
209→	transcriptData, err := ag.ReadTranscript(transcriptRef)
210→	if err != nil {
211→		return fmt.Errorf("failed to read transcript: %w", err)
212→	}
213→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
214→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
215→		return fmt.Errorf("failed to write transcript: %w", err)
216→	}
217→	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)
218→
219→	// Load pre-prompt state (captured on TurnStart)
220→	preState, err := LoadPrePromptState(sessionID)
221→	if err != nil {
222→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
223→	}
224→
225→	// Determine transcript offset
226→	transcriptOffset := resolveTranscriptOffset(preState, sessionID)
227→
228→	// Extract metadata via agent interface (prompts, summary, modified files)
229→	var allPrompts []string
230→	var summary string
231→	var modifiedFiles []string
232→	var newTranscriptPosition int
233→
234→	// Compute subagents directory for agents that support subagent extraction.
235→	// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
236→	subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
237→
238→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
239→		// Extract prompts
240→		if prompts, promptErr := analyzer.ExtractPrompts(transcriptRef, transcriptOffset); promptErr != nil {
241→			fmt.Fprintf(os.Stderr, "Warning: failed to extract prompts: %v\n", promptErr)
242→		} else {
243→			allPrompts = prompts
244→		}
245→
246→		// Extract summary
247→		if s, sumErr := analyzer.ExtractSummary(transcriptRef); sumErr != nil {
248→			fmt.Fprintf(os.Stderr, "Warning: failed to extract summary: %v\n", sumErr)
249→		} else {
250→			summary = s
251→		}
252→
253→		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
254→		if subagentExtractor, subOk := ag.(agent.SubagentAwareExtractor); subOk {
255→			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptRef, transcriptOffset, subagentsDir); fileErr != nil {
256→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files (with subagents): %v\n", fileErr)
257→			} else {
258→				modifiedFiles = files
259→			}
260→			// Get position from basic analyzer
261→			if _, pos, posErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); posErr == nil {
262→				newTranscriptPosition = pos
263→			}
264→		} else {
265→			// Fall back to basic extraction (main transcript only)
266→			if files, pos, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
267→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files: %v\n", fileErr)
268→			} else {
269→				modifiedFiles = files
270→				newTranscriptPosition = pos
271→			}
272→		}
273→	}
274→
275→	// Write prompts file
276→	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
277→	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
278→	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
279→		return fmt.Errorf("failed to write prompt file: %w", err)
280→	}
281→	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)
282→
283→	// Write summary file
284→	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
285→	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
286→		return fmt.Errorf("failed to write summary file: %w", err)
287→	}
288→	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)
289→
290→	// Generate commit message from last prompt
291→	lastPrompt := ""
292→	if len(allPrompts) > 0 {
293→		lastPrompt = allPrompts[len(allPrompts)-1]
294→	}
295→	commitMessage := generateCommitMessage(lastPrompt)
296→	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)
297→
298→	// Get repo root for path normalization
299→	repoRoot, err := paths.RepoRoot()
300→	if err != nil {
301→		return fmt.Errorf("failed to get repo root: %w", err)
302→	}
303→
304→	var preUntrackedFiles []string
305→	if preState != nil {
306→		fmt.Fprintf(os.Stderr, "Pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
307→		preUntrackedFiles = preState.PreUntrackedFiles()
308→	}
309→
310→	// Detect file changes via git status
311→	changes, err := DetectFileChanges(preUntrackedFiles)
312→	if err != nil {
313→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
314→	}
315→
316→	// Filter and normalize all paths
317→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
318→	var relNewFiles, relDeletedFiles []string
319→	if changes != nil {
320→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
321→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
322→	}
323→
324→	// Filter transcript-extracted files to exclude files already committed to HEAD.
325→	// When an agent commits files mid-turn, those files are condensed by PostCommit
326→	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
327→	// if it exists in HEAD with the same content as the working tree.
328→	relModifiedFiles = filterToUncommittedFiles(relModifiedFiles, repoRoot)
329→
330→	// Check if there are any changes
331→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
332→	if totalChanges == 0 {
333→		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
334→		fmt.Fprintf(os.Stderr, "Skipping commit\n")
335→		transitionSessionTurnEnd(sessionID)
336→		// Auto-apply pending wingman review even when no file changes this turn
337→		handleWingmanTurnEnd(sessionID, 0, nil, nil, nil, nil, "")
338→		if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
339→			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
340→		}
341→		return nil
342→	}
343→
344→	// Log file changes
345→	logFileChanges(relModifiedFiles, relNewFiles, relDeletedFiles)
346→
347→	// Create context file
348→	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
349→	if err := createContextFile(contextFile, commitMessage, sessionID, allPrompts, summary); err != nil {
350→		return fmt.Errorf("failed to create context file: %w", err)
351→	}
352→	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)
353→
354→	// Get git author
355→	author, err := GetGitAuthor()
356→	if err != nil {
357→		return fmt.Errorf("failed to get git author: %w", err)
358→	}
359→
360→	// Get strategy and agent type
361→	strat := GetStrategy()
362→	agentType := ag.Type()
363→
364→	// Get transcript position/identifier from pre-prompt state
365→	var transcriptIdentifierAtStart string
366→	var transcriptLinesAtStart int
367→	if preState != nil {
368→		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
369→		transcriptLinesAtStart = preState.TranscriptOffset
370→	}
371→
372→	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
373→	var tokenUsage *agent.TokenUsage
374→	if subagentExtractor, ok := ag.(agent.SubagentAwareExtractor); ok {
375→		usage, tokenErr := subagentExtractor.CalculateTotalTokenUsage(transcriptRef, transcriptLinesAtStart, subagentsDir)
376→		if tokenErr != nil {
377→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage (with subagents): %v\n", tokenErr)
378→		} else {
379→			tokenUsage = usage
380→		}
381→	} else if calculator, ok := ag.(agent.TokenCalculator); ok {
382→		// Fall back to basic token calculation (main transcript only)
383→		usage, tokenErr := calculator.CalculateTokenUsage(transcriptRef, transcriptLinesAtStart)
384→		if tokenErr != nil {
385→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
386→		} else {
387→			tokenUsage = usage
388→		}
389→	}
390→
391→	// Build fully-populated step context and delegate to strategy
392→	ctx := strategy.StepContext{
393→		SessionID:                sessionID,
394→		ModifiedFiles:            relModifiedFiles,
395→		NewFiles:                 relNewFiles,
396→		DeletedFiles:             relDeletedFiles,
397→		MetadataDir:              sessionDir,
398→		MetadataDirAbs:           sessionDirAbs,
399→		CommitMessage:            commitMessage,
400→		TranscriptPath:           transcriptRef,
401→		AuthorName:               author.Name,
402→		AuthorEmail:              author.Email,
403→		AgentType:                agentType,
404→		StepTranscriptIdentifier: transcriptIdentifierAtStart,
405→		StepTranscriptStart:      transcriptLinesAtStart,
406→		TokenUsage:               tokenUsage,
407→	}
408→
409→	if err := strat.SaveStep(ctx); err != nil {
410→		return fmt.Errorf("failed to save step: %w", err)
411→	}
412→
413→	// Update session state transcript position for auto-commit strategy
414→	if strat.Name() == strategy.StrategyNameAutoCommit && newTranscriptPosition > 0 {
415→		updateAutoCommitTranscriptPosition(sessionID, newTranscriptPosition)
416→	}
417→
418→	// Transition session phase and cleanup
419→	transitionSessionTurnEnd(sessionID)
420→
421→	// Wingman: trigger review (auto-commit), auto-apply, and stop notification
422→	handleWingmanTurnEnd(sessionID, totalChanges, relModifiedFiles, relNewFiles, relDeletedFiles, allPrompts, commitMessage)
423→
424→	if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
425→		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
426→	}
427→
428→	return nil
429→}
430→
431→// handleLifecycleCompaction handles context compaction: saves current progress
432→// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
433→// Also resets the transcript offset since the transcript may be truncated.
434→func handleLifecycleCompaction(ag agent.Agent, event *agent.Event) error {
435→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
436→	logging.Info(logCtx, "compaction",
437→		slog.String("event", event.Type.String()),
438→		slog.String("session_id", event.SessionID),
439→	)
440→
441→	// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
442→	sessionID := event.SessionID
443→	sessionState, loadErr := strategy.LoadSessionState(sessionID)
444→	if loadErr != nil {
445→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for compaction: %v\n", loadErr)
446→	}
447→	if sessionState != nil {
448→		if transErr := strategy.TransitionAndLog(sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
449→			fmt.Fprintf(os.Stderr, "Warning: compaction transition failed: %v\n", transErr)
450→		}
451→
452→		// Reset transcript offset since the transcript may be truncated/reorganized
453→		sessionState.CheckpointTranscriptStart = 0
454→
455→		if saveErr := strategy.SaveSessionState(sessionState); saveErr != nil {
456→			fmt.Fprintf(os.Stderr, "Warning: failed to save session state after compaction: %v\n", saveErr)
457→		}
458→	}
459→
460→	fmt.Fprintf(os.Stderr, "Context compaction: transcript offset reset\n")
461→	return nil
462→}
463→
464→// handleLifecycleSessionEnd handles session end: marks the session as ended.
465→func handleLifecycleSessionEnd(ag agent.Agent, event *agent.Event) error {
466→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
467→	logging.Info(logCtx, "session-end",
468→		slog.String("event", event.Type.String()),
469→		slog.String("session_id", event.SessionID),
470→	)
471→
472→	if event.SessionID == "" {
473→		return nil // No session to update
474→	}
475→
476→	if err := markSessionEnded(event.SessionID); err != nil {
477→		fmt.Fprintf(os.Stderr, "Warning: failed to mark session ended: %v\n", err)
478→	}
479→	return nil
480→}
481→
482→// handleLifecycleSubagentStart handles subagent start: captures pre-task state.
483→func handleLifecycleSubagentStart(ag agent.Agent, event *agent.Event) error {
484→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
485→	logging.Info(logCtx, "subagent-start",
486→		slog.String("event", event.Type.String()),
487→		slog.String("session_id", event.SessionID),
488→		slog.String("tool_use_id", event.ToolUseID),
489→	)
490→
491→	// Log context
492→	fmt.Fprintf(os.Stderr, "[entire] Subagent started\n")
493→	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
494→	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
495→	fmt.Fprintf(os.Stderr, "  Transcript: %s\n", event.SessionRef)
496→
497→	// Capture pre-task state
498→	if err := CapturePreTaskState(event.ToolUseID); err != nil {
499→		return fmt.Errorf("failed to capture pre-task state: %w", err)
500→	}
501→
502→	return nil
503→}
504→
505→// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
506→func handleLifecycleSubagentEnd(ag agent.Agent, event *agent.Event) error {
507→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
508→	logging.Info(logCtx, "subagent-end",
509→		slog.String("event", event.Type.String()),
510→		slog.String("session_id", event.SessionID),
511→		slog.String("tool_use_id", event.ToolUseID),
512→		slog.String("subagent_id", event.SubagentID),
513→	)
514→
515→	// Extract subagent type and description from tool input
516→	subagentType, taskDescription := ParseSubagentTypeAndDescription(event.ToolInput)
517→
518→	// Determine subagent transcript path
519→	transcriptDir := filepath.Dir(event.SessionRef)
520→	var subagentTranscriptPath string
521→	if event.SubagentID != "" {
522→		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
523→		if !fileExists(subagentTranscriptPath) {
524→			subagentTranscriptPath = ""
525→		}
526→	}
527→
528→	// Log context
529→	fmt.Fprintf(os.Stderr, "[entire] Subagent completed\n")
530→	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
531→	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
532→	if event.SubagentID != "" {
533→		fmt.Fprintf(os.Stderr, "  Agent ID: %s\n", event.SubagentID)
534→	}
535→	if subagentTranscriptPath != "" {
536→		fmt.Fprintf(os.Stderr, "  Subagent Transcript: %s\n", subagentTranscriptPath)
537→	}
538→
539→	// Extract modified files from subagent transcript
540→	var modifiedFiles []string
541→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
542→		transcriptToScan := event.SessionRef
543→		if subagentTranscriptPath != "" {
544→			transcriptToScan = subagentTranscriptPath
545→		}
546→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
547→			fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files from subagent: %v\n", fileErr)
548→		} else {
549→			modifiedFiles = files
550→		}
551→	}
552→
553→	// Load pre-task state and detect file changes
554→	preState, err := LoadPreTaskState(event.ToolUseID)
555→	if err != nil {
556→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
557→	}
558→	var preUntrackedFiles []string
559→	if preState != nil {
560→		preUntrackedFiles = preState.PreUntrackedFiles()
561→	}
562→	changes, err := DetectFileChanges(preUntrackedFiles)
563→	if err != nil {
564→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
565→	}
566→
567→	// Get repo root and normalize paths
568→	repoRoot, err := paths.RepoRoot()
569→	if err != nil {
570→		return fmt.Errorf("failed to get repo root: %w", err)
571→	}
572→
573→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
574→	var relNewFiles, relDeletedFiles []string
575→	if changes != nil {
576→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
577→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
578→	}
579→
580→	// If no changes, skip
581→	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
582→		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
583→		_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
584→		return nil
585→	}
586→
587→	// Find checkpoint UUID from main transcript (best-effort)
588→	var checkpointUUID string
589→	// Use the existing CLI-level checkpoint UUID finder
590→	mainLines, _, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
591→	if mainLines != nil {
592→		checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
593→	}
594→
595→	// Get git author
596→	author, err := GetGitAuthor()
597→	if err != nil {
598→		return fmt.Errorf("failed to get git author: %w", err)
599→	}
600→
601→	// Build task checkpoint context
602→	strat := GetStrategy()
603→	agentType := ag.Type()
604→
605→	ctx := strategy.TaskStepContext{
606→		SessionID:              event.SessionID,
607→		ToolUseID:              event.ToolUseID,
608→		AgentID:                event.SubagentID,
609→		ModifiedFiles:          relModifiedFiles,
610→		NewFiles:               relNewFiles,
611→		DeletedFiles:           relDeletedFiles,
612→		TranscriptPath:         event.SessionRef,
613→		SubagentTranscriptPath: subagentTranscriptPath,
614→		CheckpointUUID:         checkpointUUID,
615→		AuthorName:             author.Name,
616→		AuthorEmail:            author.Email,
617→		SubagentType:           subagentType,
618→		TaskDescription:        taskDescription,
619→		AgentType:              agentType,
620→	}
621→
622→	if err := strat.SaveTaskStep(ctx); err != nil {
623→		return fmt.Errorf("failed to save task step: %w", err)
624→	}
625→
626→	_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
627→	return nil
628→}
629→
630→// --- Helper functions ---
631→
632→// resolveTranscriptOffset determines the transcript offset to use for parsing.
633→// Prefers pre-prompt state, falls back to session state.
634→func resolveTranscriptOffset(preState *PrePromptState, sessionID string) int {
635→	if preState != nil && preState.TranscriptOffset > 0 {
636→		fmt.Fprintf(os.Stderr, "Pre-prompt state found: parsing transcript from offset %d\n", preState.TranscriptOffset)
637→		return preState.TranscriptOffset
638→	}
639→
640→	// Fall back to session state (e.g., auto-commit strategy updates it after each save)
641→	sessionState, loadErr := strategy.LoadSessionState(sessionID)
642→	if loadErr != nil {
643→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
644→		return 0
645→	}
646→	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
647→		fmt.Fprintf(os.Stderr, "Session state found: parsing transcript from offset %d\n", sessionState.CheckpointTranscriptStart)
648→		return sessionState.CheckpointTranscriptStart
649→	}
650→
651→	return 0
652→}
653→
654→// updateAutoCommitTranscriptPosition updates the session state with the new transcript position
655→// for the auto-commit strategy.
656→func updateAutoCommitTranscriptPosition(sessionID string, newPosition int) {
657→	sessionState, loadErr := strategy.LoadSessionState(sessionID)
658→	if loadErr != nil {
659→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
660→		return
661→	}
662→	if sessionState == nil {
663→		sessionState = &strategy.SessionState{
664→			SessionID: sessionID,
665→		}
666→	}
667→	sessionState.CheckpointTranscriptStart = newPosition
668→	sessionState.StepCount++
669→	if updateErr := strategy.SaveSessionState(sessionState); updateErr != nil {
670→		fmt.Fprintf(os.Stderr, "Warning: failed to update session state: %v\n", updateErr)
671→	} else {
672→		fmt.Fprintf(os.Stderr, "Updated session state: transcript position=%d, checkpoint=%d\n",
673→			newPosition, sessionState.StepCount)
674→	}
675→}
676→
677→// createContextFile creates a context.md file for the session checkpoint.
678→// This is a unified version that works for all agents.
679→func createContextFile(contextFile, commitMessage, sessionID string, prompts []string, summary string) error {
680→	var sb strings.Builder
681→
682→	sb.WriteString("# Session Context\n\n")
683→	fmt.Fprintf(&sb, "Session ID: %s\n", sessionID)
684→	fmt.Fprintf(&sb, "Commit Message: %s\n\n", commitMessage)
685→
686→	if len(prompts) > 0 {
687→		sb.WriteString("## Prompts\n\n")
688→		for i, p := range prompts {
689→			fmt.Fprintf(&sb, "### Prompt %d\n\n%s\n\n", i+1, p)
690→		}
691→	}
692→
693→	if summary != "" {
694→		sb.WriteString("## Summary\n\n")
695→		sb.WriteString(summary)
696→		sb.WriteString("\n")
697→	}
698→
699→	if err := os.WriteFile(contextFile, []byte(sb.String()), 0o600); err != nil {
700→		return fmt.Errorf("failed to write context file: %w", err)
701→	}
702→	return nil
703→}
704→
705→// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
706→// Returns parsed transcript lines for use with FindCheckpointUUID.
707→func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, int, error) {
708→	lines, total, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
709→	if err != nil {
710→		return nil, 0, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
711→	}
712→	return lines, total, nil
713→}
714→
715→// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
716→func transitionSessionTurnEnd(sessionID string) {
717→	turnState, loadErr := strategy.LoadSessionState(sessionID)
718→	if loadErr != nil {
719→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for turn end: %v\n", loadErr)
720→		return
721→	}
722→	if turnState == nil {
723→		return
724→	}
725→	if err := strategy.TransitionAndLog(turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
726→		fmt.Fprintf(os.Stderr, "Warning: turn-end transition failed: %v\n", err)
727→	}
728→
729→	// Always dispatch to strategy for turn-end handling. The strategy reads
730→	// work items from state (e.g. TurnCheckpointIDs), not the action list.
731→	strat := GetStrategy()
732→	if handler, ok := strat.(strategy.TurnEndHandler); ok {
733→		if err := handler.HandleTurnEnd(turnState); err != nil {
734→			fmt.Fprintf(os.Stderr, "Warning: turn-end action dispatch failed: %v\n", err)
735→		}
736→	}
737→
738→	if updateErr := strategy.SaveSessionState(turnState); updateErr != nil {
739→		fmt.Fprintf(os.Stderr, "Warning: failed to update session phase on turn end: %v\n", updateErr)
740→	}
741→}
742→
743→// markSessionEnded transitions the session to ENDED phase via the state machine.
744→func markSessionEnded(sessionID string) error {
745→	state, err := strategy.LoadSessionState(sessionID)
746→	if err != nil {
747→		return fmt.Errorf("failed to load session state: %w", err)
748→	}
749→	if state == nil {
750→		return nil // No state file, nothing to update
751→	}
752→
753→	if transErr := strategy.TransitionAndLog(state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
754→		fmt.Fprintf(os.Stderr, "Warning: session stop transition failed: %v\n", transErr)
755→	}
756→
757→	now := time.Now()
758→	state.EndedAt = &now
759→
760→	if err := strategy.SaveSessionState(state); err != nil {
761→		return fmt.Errorf("failed to save session state: %w", err)
762→	}
763→	return nil
764→}
765→
766→// logFileChanges logs the files modified, created, and deleted during a session.
767→func logFileChanges(modified, newFiles, deleted []string) {
768→	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(modified))
769→	for _, file := range modified {
770→		fmt.Fprintf(os.Stderr, "  - %s\n", file)
771→	}
772→	if len(newFiles) > 0 {
773→		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(newFiles))
774→		for _, file := range newFiles {
775→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
776→		}
777→	}
778→	if len(deleted) > 0 {
779→		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(deleted))
780→		for _, file := range deleted {
781→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
782→		}
783→	}
784→}
