// lifecycle.go implements the generic lifecycle event dispatcher.
// It routes normalized events from any agent to the appropriate framework actions.
//
// The dispatcher inverts the current flow from "agent handler calls framework functions"
// to "framework dispatcher calls agent methods." Agents are passive data providers;
// the dispatcher handles all orchestration: state transitions, strategy calls,
// file change detection, metadata generation.
package cli

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
// Returns nil if the event was handled successfully.
func DispatchLifecycleEvent(ag agent.Agent, event *agent.Event) error {
	if ag == nil {
		return errors.New("agent cannot be nil")
	}
	if event == nil {
		return errors.New("event cannot be nil")
	}

	switch event.Type {
	case agent.SessionStart:
		return handleLifecycleSessionStart(ag, event)
	case agent.TurnStart:
		return handleLifecycleTurnStart(ag, event)
	case agent.TurnEnd:
		return handleLifecycleTurnEnd(ag, event)
	case agent.Compaction:
		return handleLifecycleCompaction(ag, event)
	case agent.SessionEnd:
		return handleLifecycleSessionEnd(ag, event)
	case agent.SubagentStart:
		return handleLifecycleSubagentStart(ag, event)
	case agent.SubagentEnd:
		return handleLifecycleSubagentEnd(ag, event)
	default:
		return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
	}
}

// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
// fires state machine transition.
func handleLifecycleSessionStart(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
	)

	if event.SessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(event.SessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Build informational message
	message := "\n\nPowered by Entire:\n  This conversation will be linked to your next commit."

	// Append wingman status if enabled
	message = appendWingmanSessionStartStatus(message)

	// Check for concurrent sessions and append count if any
	strat := GetStrategy()
	if concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker); ok {
		if count, err := concurrentChecker.CountOtherActiveSessionsWithCheckpoints(event.SessionID); err == nil && count > 0 {
			message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
		}
	}

	// Output informational message
	if event.ResponseMessage != "" {
		message = event.ResponseMessage
	}
	if err := outputHookResponse(message); err != nil {
		return err
	}

	// Fire EventSessionStart for the current session (if state exists).
	if state, loadErr := strategy.LoadSessionState(event.SessionID); loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state on start: %v\n", loadErr)
	} else if state != nil {
		if transErr := strategy.TransitionAndLog(state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: session start transition failed: %v\n", transErr)
		}
		if saveErr := strategy.SaveSessionState(state); saveErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to update session state on start: %v\n", saveErr)
		}
	}

	return nil
}

// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
// ensures strategy setup, initializes session.
func handleLifecycleTurnStart(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
	if err := CapturePrePromptState(ag, sessionID, event.SessionRef); err != nil {
		return err
	}

	// If a wingman review is pending, inject it as additionalContext so the
	// agent addresses it BEFORE the user's request. Must return early to
	// avoid corrupting the JSON stdout with additional output.
	if handleWingmanTurnStart(sessionID) {
		return nil
	}

	// Ensure strategy setup and initialize session
	strat := GetStrategy()

	if err := strat.EnsureSetup(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
	}

	if initializer, ok := strat.(strategy.SessionInitializer); ok {
		agentType := ag.Type()
		if err := initializer.InitializeSession(sessionID, agentType, event.SessionRef, event.Prompt); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to initialize session state: %v\n", err)
		}
	}

	return nil
}

// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
// detects file changes, saves step + checkpoint, transitions phase.
//
//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
func handleLifecycleTurnEnd(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		sessionID = unknownSessionID
	}

	transcriptRef := event.SessionRef
	if transcriptRef == "" {
		return errors.New("transcript file not specified")
	}
	if !fileExists(transcriptRef) {
		return fmt.Errorf("transcript file not found: %s", transcriptRef)
	}

	// Early check: bail out quickly if the repo has no commits yet.
	if repo, err := strategy.OpenRepository(); err == nil && strategy.IsEmptyRepository(repo) {
		fmt.Fprintln(os.Stderr, "Entire: skipping checkpoint. Will activate after first commit.")
		return NewSilentError(strategy.ErrEmptyRepository)
	}

	// Create session metadata directory
	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
	sessionDirAbs, err := paths.AbsPath(sessionDir)
	if err != nil {
		sessionDirAbs = sessionDir
	}
	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// If agent implements TranscriptPreparer, wait for transcript to be ready
	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
		if err := preparer.PrepareTranscript(transcriptRef); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to prepare transcript: %v\n", err)
		}
	}

	// Copy transcript to session directory
	transcriptData, err := ag.ReadTranscript(transcriptRef)
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}
	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)

	// Load pre-prompt state (captured on TurnStart)
	preState, err := LoadPrePromptState(sessionID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
	}

	// Determine transcript offset
	transcriptOffset := resolveTranscriptOffset(preState, sessionID)

	// Extract metadata via agent interface (prompts, summary, modified files)
	var allPrompts []string
	var summary string
	var modifiedFiles []string
	var newTranscriptPosition int

	// Compute subagents directory for agents that support subagent extraction.
	// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
	subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")

	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
		// Extract prompts
		if prompts, promptErr := analyzer.ExtractPrompts(transcriptRef, transcriptOffset); promptErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to extract prompts: %v\n", promptErr)
		} else {
			allPrompts = prompts
		}

		// Extract summary
		if s, sumErr := analyzer.ExtractSummary(transcriptRef); sumErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to extract summary: %v\n", sumErr)
		} else {
			summary = s
		}

		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
		if subagentExtractor, subOk := ag.(agent.SubagentAwareExtractor); subOk {
			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptRef, transcriptOffset, subagentsDir); fileErr != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files (with subagents): %v\n", fileErr)
			} else {
				modifiedFiles = files
			}
			// Get position from basic analyzer
			if _, pos, posErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); posErr == nil {
				newTranscriptPosition = pos
			}
		} else {
			// Fall back to basic extraction (main transcript only)
			if files, pos, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files: %v\n", fileErr)
			} else {
				modifiedFiles = files
				newTranscriptPosition = pos
			}
		}
	}

	// Write prompts file
	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
		return fmt.Errorf("failed to write prompt file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)

	// Write summary file
	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
		return fmt.Errorf("failed to write summary file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)

	// Generate commit message from last prompt
	lastPrompt := ""
	if len(allPrompts) > 0 {
		lastPrompt = allPrompts[len(allPrompts)-1]
	}
	commitMessage := generateCommitMessage(lastPrompt)
	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)

	// Get repo root for path normalization
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repo root: %w", err)
	}

	var preUntrackedFiles []string
	if preState != nil {
		fmt.Fprintf(os.Stderr, "Pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
		preUntrackedFiles = preState.PreUntrackedFiles()
	}

	// Detect file changes via git status
	changes, err := DetectFileChanges(preUntrackedFiles)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
	}

	// Filter and normalize all paths
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	var relNewFiles, relDeletedFiles []string
	if changes != nil {
		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
	}

	// Filter transcript-extracted files to exclude files already committed to HEAD.
	// When an agent commits files mid-turn, those files are condensed by PostCommit
	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
	// if it exists in HEAD with the same content as the working tree.
	relModifiedFiles = filterToUncommittedFiles(relModifiedFiles, repoRoot)

	// Check if there are any changes
	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
	if totalChanges == 0 {
		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
		fmt.Fprintf(os.Stderr, "Skipping commit\n")
		transitionSessionTurnEnd(sessionID)
		// Auto-apply pending wingman review even when no file changes this turn
		handleWingmanTurnEnd(sessionID, 0, nil, nil, nil, nil, "")
		if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
		}
		return nil
	}

	// Log file changes
	logFileChanges(relModifiedFiles, relNewFiles, relDeletedFiles)

	// Create context file
	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
	if err := createContextFile(contextFile, commitMessage, sessionID, allPrompts, summary); err != nil {
		return fmt.Errorf("failed to create context file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)

	// Get git author
	author, err := GetGitAuthor()
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Get strategy and agent type
	strat := GetStrategy()
	agentType := ag.Type()

	// Get transcript position/identifier from pre-prompt state
	var transcriptIdentifierAtStart string
	var transcriptLinesAtStart int
	if preState != nil {
		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
		transcriptLinesAtStart = preState.TranscriptOffset
	}

	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
	var tokenUsage *agent.TokenUsage
	if subagentExtractor, ok := ag.(agent.SubagentAwareExtractor); ok {
		usage, tokenErr := subagentExtractor.CalculateTotalTokenUsage(transcriptRef, transcriptLinesAtStart, subagentsDir)
		if tokenErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage (with subagents): %v\n", tokenErr)
		} else {
			tokenUsage = usage
		}
	} else if calculator, ok := ag.(agent.TokenCalculator); ok {
		// Fall back to basic token calculation (main transcript only)
		usage, tokenErr := calculator.CalculateTokenUsage(transcriptRef, transcriptLinesAtStart)
		if tokenErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
		} else {
			tokenUsage = usage
		}
	}

	// Build fully-populated step context and delegate to strategy
	ctx := strategy.StepContext{
		SessionID:                sessionID,
		ModifiedFiles:            relModifiedFiles,
		NewFiles:                 relNewFiles,
		DeletedFiles:             relDeletedFiles,
		MetadataDir:              sessionDir,
		MetadataDirAbs:           sessionDirAbs,
		CommitMessage:            commitMessage,
		TranscriptPath:           transcriptRef,
		AuthorName:               author.Name,
		AuthorEmail:              author.Email,
		AgentType:                agentType,
		StepTranscriptIdentifier: transcriptIdentifierAtStart,
		StepTranscriptStart:      transcriptLinesAtStart,
		TokenUsage:               tokenUsage,
	}

	if err := strat.SaveStep(ctx); err != nil {
		return fmt.Errorf("failed to save step: %w", err)
	}

	// Update session state transcript position for auto-commit strategy
	if strat.Name() == strategy.StrategyNameAutoCommit && newTranscriptPosition > 0 {
		updateAutoCommitTranscriptPosition(sessionID, newTranscriptPosition)
	}

	// Transition session phase and cleanup
	transitionSessionTurnEnd(sessionID)

	// Wingman: trigger review (auto-commit), auto-apply, and stop notification
	handleWingmanTurnEnd(sessionID, totalChanges, relModifiedFiles, relNewFiles, relDeletedFiles, allPrompts, commitMessage)

	if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
	}

	return nil
}

// handleLifecycleCompaction handles context compaction: saves current progress
// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
// Also resets the transcript offset since the transcript may be truncated.
func handleLifecycleCompaction(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "compaction",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
	sessionID := event.SessionID
	sessionState, loadErr := strategy.LoadSessionState(sessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for compaction: %v\n", loadErr)
	}
	if sessionState != nil {
		if transErr := strategy.TransitionAndLog(sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: compaction transition failed: %v\n", transErr)
		}

		// Reset transcript offset since the transcript may be truncated/reorganized
		sessionState.CheckpointTranscriptStart = 0

		if saveErr := strategy.SaveSessionState(sessionState); saveErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to save session state after compaction: %v\n", saveErr)
		}
	}

	fmt.Fprintf(os.Stderr, "Context compaction: transcript offset reset\n")
	return nil
}

// handleLifecycleSessionEnd handles session end: marks the session as ended.
func handleLifecycleSessionEnd(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if event.SessionID == "" {
		return nil // No session to update
	}

	if err := markSessionEnded(event.SessionID); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to mark session ended: %v\n", err)
	}
	return nil
}

// handleLifecycleSubagentStart handles subagent start: captures pre-task state.
func handleLifecycleSubagentStart(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "subagent-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("tool_use_id", event.ToolUseID),
	)

	// Log context
	fmt.Fprintf(os.Stderr, "[entire] Subagent started\n")
	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
	fmt.Fprintf(os.Stderr, "  Transcript: %s\n", event.SessionRef)

	// Capture pre-task state
	if err := CapturePreTaskState(event.ToolUseID); err != nil {
		return fmt.Errorf("failed to capture pre-task state: %w", err)
	}

	return nil
}

// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
func handleLifecycleSubagentEnd(ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
	logging.Info(logCtx, "subagent-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("tool_use_id", event.ToolUseID),
		slog.String("subagent_id", event.SubagentID),
	)

	// Extract subagent type and description from tool input
	subagentType, taskDescription := ParseSubagentTypeAndDescription(event.ToolInput)

	// Determine subagent transcript path
	transcriptDir := filepath.Dir(event.SessionRef)
	var subagentTranscriptPath string
	if event.SubagentID != "" {
		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
		if !fileExists(subagentTranscriptPath) {
			subagentTranscriptPath = ""
		}
	}

	// Log context
	fmt.Fprintf(os.Stderr, "[entire] Subagent completed\n")
	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
	if event.SubagentID != "" {
		fmt.Fprintf(os.Stderr, "  Agent ID: %s\n", event.SubagentID)
	}
	if subagentTranscriptPath != "" {
		fmt.Fprintf(os.Stderr, "  Subagent Transcript: %s\n", subagentTranscriptPath)
	}

	// Extract modified files from subagent transcript
	var modifiedFiles []string
	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
		transcriptToScan := event.SessionRef
		if subagentTranscriptPath != "" {
			transcriptToScan = subagentTranscriptPath
		}
		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files from subagent: %v\n", fileErr)
		} else {
			modifiedFiles = files
		}
	}

	// Load pre-task state and detect file changes
	preState, err := LoadPreTaskState(event.ToolUseID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
	}
	var preUntrackedFiles []string
	if preState != nil {
		preUntrackedFiles = preState.PreUntrackedFiles()
	}
	changes, err := DetectFileChanges(preUntrackedFiles)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
	}

	// Get repo root and normalize paths
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repo root: %w", err)
	}

	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	var relNewFiles, relDeletedFiles []string
	if changes != nil {
		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
	}

	// If no changes, skip
	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
		_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
		return nil
	}

	// Find checkpoint UUID from main transcript (best-effort)
	var checkpointUUID string
	// Use the existing CLI-level checkpoint UUID finder
	mainLines, _, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
	if mainLines != nil {
		checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
	}

	// Get git author
	author, err := GetGitAuthor()
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Build task checkpoint context
	strat := GetStrategy()
	agentType := ag.Type()

	ctx := strategy.TaskStepContext{
		SessionID:              event.SessionID,
		ToolUseID:              event.ToolUseID,
		AgentID:                event.SubagentID,
		ModifiedFiles:          relModifiedFiles,
		NewFiles:               relNewFiles,
		DeletedFiles:           relDeletedFiles,
		TranscriptPath:         event.SessionRef,
		SubagentTranscriptPath: subagentTranscriptPath,
		CheckpointUUID:         checkpointUUID,
		AuthorName:             author.Name,
		AuthorEmail:            author.Email,
		SubagentType:           subagentType,
		TaskDescription:        taskDescription,
		AgentType:              agentType,
	}

	if err := strat.SaveTaskStep(ctx); err != nil {
		return fmt.Errorf("failed to save task step: %w", err)
	}

	_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
	return nil
}

// --- Helper functions ---

// resolveTranscriptOffset determines the transcript offset to use for parsing.
// Prefers pre-prompt state, falls back to session state.
func resolveTranscriptOffset(preState *PrePromptState, sessionID string) int {
	if preState != nil && preState.TranscriptOffset > 0 {
		fmt.Fprintf(os.Stderr, "Pre-prompt state found: parsing transcript from offset %d\n", preState.TranscriptOffset)
		return preState.TranscriptOffset
	}

	// Fall back to session state (e.g., auto-commit strategy updates it after each save)
	sessionState, loadErr := strategy.LoadSessionState(sessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
		return 0
	}
	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
		fmt.Fprintf(os.Stderr, "Session state found: parsing transcript from offset %d\n", sessionState.CheckpointTranscriptStart)
		return sessionState.CheckpointTranscriptStart
	}

	return 0
}

// updateAutoCommitTranscriptPosition updates the session state with the new transcript position
// for the auto-commit strategy.
func updateAutoCommitTranscriptPosition(sessionID string, newPosition int) {
	sessionState, loadErr := strategy.LoadSessionState(sessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
		return
	}
	if sessionState == nil {
		sessionState = &strategy.SessionState{
			SessionID: sessionID,
		}
	}
	sessionState.CheckpointTranscriptStart = newPosition
	sessionState.StepCount++
	if updateErr := strategy.SaveSessionState(sessionState); updateErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to update session state: %v\n", updateErr)
	} else {
		fmt.Fprintf(os.Stderr, "Updated session state: transcript position=%d, checkpoint=%d\n",
			newPosition, sessionState.StepCount)
	}
}

// createContextFile creates a context.md file for the session checkpoint.
// This is a unified version that works for all agents.
func createContextFile(contextFile, commitMessage, sessionID string, prompts []string, summary string) error {
	var sb strings.Builder

	sb.WriteString("# Session Context\n\n")
	fmt.Fprintf(&sb, "Session ID: %s\n", sessionID)
	fmt.Fprintf(&sb, "Commit Message: %s\n\n", commitMessage)

	if len(prompts) > 0 {
		sb.WriteString("## Prompts\n\n")
		for i, p := range prompts {
			fmt.Fprintf(&sb, "### Prompt %d\n\n%s\n\n", i+1, p)
		}
	}

	if summary != "" {
		sb.WriteString("## Summary\n\n")
		sb.WriteString(summary)
		sb.WriteString("\n")
	}

	if err := os.WriteFile(contextFile, []byte(sb.String()), 0o600); err != nil {
		return fmt.Errorf("failed to write context file: %w", err)
	}
	return nil
}

// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
// Returns parsed transcript lines for use with FindCheckpointUUID.
func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, int, error) {
	lines, total, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
	if err != nil {
		return nil, 0, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
	}
	return lines, total, nil
}

// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
func transitionSessionTurnEnd(sessionID string) {
	turnState, loadErr := strategy.LoadSessionState(sessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for turn end: %v\n", loadErr)
		return
	}
	if turnState == nil {
		return
	}
	if err := strategy.TransitionAndLog(turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: turn-end transition failed: %v\n", err)
	}

	// Always dispatch to strategy for turn-end handling. The strategy reads
	// work items from state (e.g. TurnCheckpointIDs), not the action list.
	strat := GetStrategy()
	if handler, ok := strat.(strategy.TurnEndHandler); ok {
		if err := handler.HandleTurnEnd(turnState); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: turn-end action dispatch failed: %v\n", err)
		}
	}

	if updateErr := strategy.SaveSessionState(turnState); updateErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to update session phase on turn end: %v\n", updateErr)
	}
}

// markSessionEnded transitions the session to ENDED phase via the state machine.
func markSessionEnded(sessionID string) error {
	state, err := strategy.LoadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state == nil {
		return nil // No state file, nothing to update
	}

	if transErr := strategy.TransitionAndLog(state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: session stop transition failed: %v\n", transErr)
	}

	now := time.Now()
	state.EndedAt = &now

	if err := strategy.SaveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}
	return nil
}

// logFileChanges logs the files modified, created, and deleted during a session.
func logFileChanges(modified, newFiles, deleted []string) {
	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(modified))
	for _, file := range modified {
		fmt.Fprintf(os.Stderr, "  - %s\n", file)
	}
	if len(newFiles) > 0 {
		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(newFiles))
		for _, file := range newFiles {
			fmt.Fprintf(os.Stderr, "  - %s\n", file)
		}
	}
	if len(deleted) > 0 {
		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(deleted))
		for _, file := range deleted {
			fmt.Fprintf(os.Stderr, "  - %s\n", file)
		}
	}
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/spf13/cobra"
)

// wingmanLog writes a timestamped log line to stderr. In the detached subprocess,
// stderr is redirected to .entire/logs/wingman.log by the spawner.
func wingmanLog(format string, args ...any) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "%s [wingman] %s\n", time.Now().Format(time.RFC3339), msg)
}

const (
	// wingmanInitialDelay is how long to wait before starting the review,
	// letting the agent turn fully settle.
	wingmanInitialDelay = 10 * time.Second

	// wingmanDefaultReviewModel is the default model used for wingman reviews.
	// Can be overridden via strategy_options.wingman.model in settings.
	wingmanDefaultReviewModel = "opus"

	// wingmanGitTimeout is the timeout for git diff operations.
	wingmanGitTimeout = 60 * time.Second

	// wingmanReviewTimeout is the timeout for the claude --print review call.
	wingmanReviewTimeout = 5 * time.Minute

	// wingmanApplyTimeout is the timeout for the claude --continue auto-apply call.
	wingmanApplyTimeout = 15 * time.Minute
)

func newWingmanReviewCmd() *cobra.Command {
	return &cobra.Command{
		Use:    "__review",
		Hidden: true,
		Args:   cobra.ExactArgs(1),
		RunE: func(_ *cobra.Command, args []string) error {
			return runWingmanReview(args[0])
		},
	}
}

func runWingmanReview(payloadPath string) error {
	wingmanLog("review process started (pid=%d)", os.Getpid())
	wingmanLog("reading payload from %s", payloadPath)

	// Read payload from file (avoids OS argv limits with large payloads)
	payloadJSON, err := os.ReadFile(payloadPath) //nolint:gosec // path is from our own spawn
	if err != nil {
		wingmanLog("ERROR reading payload: %v", err)
		return fmt.Errorf("failed to read payload file: %w", err)
	}
	// Clean up payload file after reading
	_ = os.Remove(payloadPath)

	var payload WingmanPayload
	if err := json.Unmarshal(payloadJSON, &payload); err != nil {
		wingmanLog("ERROR unmarshaling payload: %v", err)
		return fmt.Errorf("failed to unmarshal payload: %w", err)
	}

	repoRoot := payload.RepoRoot
	if repoRoot == "" {
		wingmanLog("ERROR repo_root is empty in payload")
		return errors.New("repo_root is required in payload")
	}

	totalFiles := len(payload.ModifiedFiles) + len(payload.NewFiles) + len(payload.DeletedFiles)
	wingmanLog("session=%s repo=%s base_commit=%s files=%d",
		payload.SessionID, repoRoot, payload.BaseCommit, totalFiles)

	// Clean up lock file when review completes (regardless of success/failure)
	lockPath := filepath.Join(repoRoot, wingmanLockFile)
	defer func() {
		if err := os.Remove(lockPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			wingmanLog("WARNING: failed to remove lock file: %v", err)
		} else {
			wingmanLog("lock file removed")
		}
	}()

	// Initial delay: let the agent turn fully settle
	wingmanLog("waiting %s for agent turn to settle", wingmanInitialDelay)
	time.Sleep(wingmanInitialDelay)

	// Compute diff using the base commit captured at trigger time
	wingmanLog("computing diff (merge-base with main/master)")
	diffStart := time.Now()
	diff, err := computeDiff(repoRoot)
	if err != nil {
		wingmanLog("ERROR computing diff: %v", err)
		return fmt.Errorf("failed to compute diff: %w", err)
	}

	if strings.TrimSpace(diff) == "" {
		wingmanLog("no changes found in diff, exiting")
		return nil // No changes to review
	}
	wingmanLog("diff computed: %d bytes in %s", len(diff), time.Since(diffStart).Round(time.Millisecond))

	// Build file list for the prompt
	allFiles := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
	for _, f := range payload.ModifiedFiles {
		allFiles = append(allFiles, f+" (modified)")
	}
	for _, f := range payload.NewFiles {
		allFiles = append(allFiles, f+" (new)")
	}
	for _, f := range payload.DeletedFiles {
		allFiles = append(allFiles, f+" (deleted)")
	}
	fileList := strings.Join(allFiles, ", ")

	// Read session context from checkpoint data (best-effort)
	sessionContext := readSessionContext(repoRoot, payload.SessionID)
	if sessionContext != "" {
		wingmanLog("session context loaded: %d bytes", len(sessionContext))
	}

	// Build review prompt
	prompt := buildReviewPrompt(payload.Prompts, payload.CommitMessage, sessionContext, payload.SessionID, fileList, diff)
	wingmanLog("review prompt built: %d bytes", len(prompt))

	// Call agent for review
	model := resolveWingmanModel()
	wingmanLog("calling agent for review (model=%s, timeout=%s)", model, wingmanReviewTimeout)
	reviewStart := time.Now()
	reviewText, err := callAgentForReview(repoRoot, prompt, model)
	if err != nil {
		wingmanLog("ERROR agent review failed after %s: %v", time.Since(reviewStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to get review from agent: %w", err)
	}
	wingmanLog("review received: %d bytes in %s", len(reviewText), time.Since(reviewStart).Round(time.Millisecond))

	// Write REVIEW.md
	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if err := os.MkdirAll(filepath.Dir(reviewPath), 0o750); err != nil {
		wingmanLog("ERROR creating directory: %v", err)
		return fmt.Errorf("failed to create directory: %w", err)
	}
	//nolint:gosec // G306: review file is not secrets
	if err := os.WriteFile(reviewPath, []byte(reviewText), 0o644); err != nil {
		wingmanLog("ERROR writing REVIEW.md: %v", err)
		return fmt.Errorf("failed to write REVIEW.md: %w", err)
	}
	wingmanLog("REVIEW.md written to %s", reviewPath)

	// Update dedup state — write directly to known path instead of using
	// os.Chdir (which mutates process-wide state).
	allFilePaths := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
	allFilePaths = append(allFilePaths, payload.ModifiedFiles...)
	allFilePaths = append(allFilePaths, payload.NewFiles...)
	allFilePaths = append(allFilePaths, payload.DeletedFiles...)

	saveWingmanStateDirect(repoRoot, &WingmanState{
		SessionID:     payload.SessionID,
		FilesHash:     computeFilesHash(allFilePaths),
		ReviewedAt:    time.Now(),
		ReviewApplied: false,
	})
	wingmanLog("dedup state saved")

	// If any session is live (IDLE/ACTIVE/ACTIVE_COMMITTED), don't auto-apply
	// in the background. The prompt-submit hook will inject REVIEW.md as
	// additionalContext when the user sends their next prompt — this is VISIBLE
	// in their terminal. Only use background auto-apply when no sessions are
	// alive (e.g., user closed all sessions).
	if hasAnyLiveSession(repoRoot) {
		wingmanLog("live session detected, deferring to prompt-submit injection (visible)")
		return nil
	}

	// No live sessions — apply in background as fallback
	wingmanLog("no live sessions, triggering background auto-apply")
	now := time.Now()
	state := loadWingmanStateDirect(repoRoot)
	if state != nil {
		state.ApplyAttemptedAt = &now
		saveWingmanStateDirect(repoRoot, state)
	}

	applyStart := time.Now()
	if err := triggerAutoApply(repoRoot); err != nil {
		wingmanLog("ERROR auto-apply failed after %s: %v", time.Since(applyStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to trigger auto-apply: %w", err)
	}
	wingmanLog("auto-apply completed in %s", time.Since(applyStart).Round(time.Millisecond))

	return nil
}

// computeDiff gets the full branch diff for review. It diffs the current HEAD
// against the merge base with the default branch (main/master), giving the
// reviewer a holistic view of all branch changes rather than just one commit.
func computeDiff(repoRoot string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), wingmanGitTimeout)
	defer cancel()

	// Find the merge base with the default branch for a holistic branch diff.
	mergeBase := findMergeBase(ctx, repoRoot)
	if mergeBase != "" {
		wingmanLog("using merge-base %s for branch diff", mergeBase)
		diff, err := gitDiff(ctx, repoRoot, mergeBase)
		if err == nil && strings.TrimSpace(diff) != "" {
			return diff, nil
		}
		// Fall through to HEAD diff if merge-base diff fails or is empty
	}

	// Fallback: diff uncommitted changes against HEAD
	wingmanLog("falling back to HEAD diff")
	diff, err := gitDiff(ctx, repoRoot, "HEAD")
	if err != nil {
		return "", fmt.Errorf("git diff failed: %w", err)
	}

	// If no uncommitted changes, try the latest commit itself
	if strings.TrimSpace(diff) == "" {
		diff, err = gitDiff(ctx, repoRoot, "HEAD~1", "HEAD")
		if err != nil {
			return "", fmt.Errorf("git diff for latest commit failed: %w", err)
		}
	}

	return diff, nil
}

// findMergeBase returns the merge-base commit between HEAD and the default
// branch (tries main, then master). Returns empty string if not found.
func findMergeBase(ctx context.Context, repoRoot string) string {
	for _, branch := range []string{"main", "master"} {
		cmd := exec.CommandContext(ctx, "git", "merge-base", branch, "HEAD") //nolint:gosec // branch is from hardcoded slice
		cmd.Dir = repoRoot
		out, err := cmd.Output()
		if err == nil {
			return strings.TrimSpace(string(out))
		}
	}
	return ""
}

// gitDiff runs git diff with the given args and returns stdout.
func gitDiff(ctx context.Context, repoRoot string, args ...string) (string, error) {
	fullArgs := append([]string{"diff"}, args...)
	cmd := exec.CommandContext(ctx, "git", fullArgs...) //nolint:gosec // args are from internal logic
	cmd.Dir = repoRoot
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git diff %v: %w (stderr: %s)", args, err, stderr.String())
	}
	return stdout.String(), nil
}

// resolveWingmanModel returns the model to use for wingman reviews,
// reading from settings with a fallback to the default.
func resolveWingmanModel() string {
	s, err := settings.Load()
	if err != nil {
		return wingmanDefaultReviewModel
	}
	if m := s.WingmanModel(); m != "" {
		return m
	}
	return wingmanDefaultReviewModel
}

// resolveWingmanAgent returns the agent name to use for wingman reviews,
// reading from settings with a fallback to the default agent.
func resolveWingmanAgent() agent.AgentName {
	s, err := settings.Load()
	if err != nil {
		return agent.DefaultAgentName
	}
	if a := s.WingmanAgent(); a != "" {
		return agent.AgentName(a)
	}
	return agent.DefaultAgentName
}

// callAgentForReview invokes the configured agent's Prompter to perform a review.
// repoRoot is the repository root so the reviewer can access the full codebase.
func callAgentForReview(repoRoot, prompt, model string) (string, error) {
	agentName := resolveWingmanAgent()

	ag, err := agent.Get(agentName)
	if err != nil {
		return "", fmt.Errorf("wingman agent %q not found: %w", agentName, err)
	}

	prompter, ok := ag.(agent.Prompter)
	if !ok {
		return "", fmt.Errorf("agent %q does not support prompting (does not implement agent.Prompter)", agentName)
	}

	ctx, cancel := context.WithTimeout(context.Background(), wingmanReviewTimeout)
	defer cancel()

	// Grant read-only tool access so the reviewer can inspect source files
	// beyond just the diff. Permission bypass is safe here since tools are
	// restricted to read-only operations.
	result, err := prompter.Prompt(ctx, prompt, agent.PromptOptions{
		Model:          model,
		WorkDir:        repoRoot,
		AllowedTools:   "Read,Glob,Grep",
		PermissionMode: "bypassPermissions",
	})
	if err != nil {
		return "", fmt.Errorf("agent review prompt failed: %w", err)
	}

	return result.Text, nil
}

// readSessionContext reads the context.md file from the session's checkpoint
// metadata directory. Returns empty string if unavailable.
func readSessionContext(repoRoot, sessionID string) string {
	if sessionID == "" {
		return ""
	}
	contextPath := filepath.Join(repoRoot, ".entire", "metadata", sessionID, "context.md")
	data, err := os.ReadFile(contextPath) //nolint:gosec // path constructed from repoRoot + session ID
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			wingmanLog("WARNING: failed to read session context: %v", err)
		}
		return ""
	}
	return string(data)
}

// staleActiveSessionThreshold is the maximum age of a session state file in an
// ACTIVE phase before it is considered stale (crashed agent) and ignored by
// hasAnyLiveSession. Only applies to ACTIVE/ACTIVE_COMMITTED phases — an IDLE
// session is always considered live regardless of age (user may just be away).
const staleActiveSessionThreshold = 4 * time.Hour

// hasAnyLiveSession checks if any session is in a non-ENDED phase (IDLE,
// ACTIVE, or ACTIVE_COMMITTED). Used to decide whether to defer review
// application to the prompt-submit injection (visible to user) vs background
// auto-apply (invisible).
//
// ACTIVE/ACTIVE_COMMITTED sessions older than staleActiveSessionThreshold are
// skipped as likely orphaned from crashed processes. IDLE sessions are always
// considered live regardless of age.
func hasAnyLiveSession(repoRoot string) bool {
	sessDir := findSessionStateDir(repoRoot)
	if sessDir == "" {
		return false
	}

	entries, err := os.ReadDir(sessDir)
	if err != nil {
		return false
	}

	const maxCheck = 50
	checked := 0
	for _, entry := range entries {
		if checked >= maxCheck {
			wingmanLog("stopping live-session scan after %d entries; assuming live session may exist", checked)
			return true
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".json") {
			continue
		}
		checked++

		sid := strings.TrimSuffix(name, ".json")
		info := readSessionPhaseInfo(sessDir, sid)
		if info.Phase == "" || info.Phase == string(session.PhaseEnded) {
			continue
		}

		// ACTIVE/ACTIVE_COMMITTED sessions that haven't had a real agent
		// interaction in a long time are likely orphaned from crashed agents.
		// Uses LastInteractionTime from JSON (not file modtime) because
		// PostCommit saves all session files on every commit, refreshing
		// modtime even for stale sessions.
		// IDLE sessions are always considered live (user may just be away).
		if session.PhaseFromString(info.Phase).IsActive() {
			if info.LastInteractionTime != nil && time.Since(*info.LastInteractionTime) > staleActiveSessionThreshold {
				wingmanLog("skipping stale active session %s (phase=%s, last_interaction=%s ago)", sid, info.Phase, time.Since(*info.LastInteractionTime).Round(time.Second))
				continue
			}
		}

		wingmanLog("found live session %s (phase=%s)", sid, info.Phase)
		return true
	}

	return false
}

// findSessionStateDir locates the .git/entire-sessions/ directory by
// reading .git to handle both normal repos and worktrees.
func findSessionStateDir(repoRoot string) string {
	gitPath := filepath.Join(repoRoot, ".git")
	info, err := os.Stat(gitPath)
	if err != nil {
		return ""
	}

	var gitDir string
	if info.IsDir() {
		// Normal repo: .git is a directory
		gitDir = gitPath
	} else {
		// Worktree: .git is a file containing "gitdir: <path>"
		data, readErr := os.ReadFile(gitPath) //nolint:gosec // path from repoRoot
		if readErr != nil {
			return ""
		}
		content := strings.TrimSpace(string(data))
		if !strings.HasPrefix(content, "gitdir: ") {
			return ""
		}
		gitDir = strings.TrimPrefix(content, "gitdir: ")
		if !filepath.IsAbs(gitDir) {
			gitDir = filepath.Join(repoRoot, gitDir)
		}
		// For worktrees, session state is in the common dir
		// .git/worktrees/<name> → ../../ is the common .git dir
		commonDir := filepath.Join(gitDir, "..", "..")
		gitDir = filepath.Clean(commonDir)
	}

	sessDir := filepath.Join(gitDir, "entire-sessions")
	if _, statErr := os.Stat(sessDir); statErr != nil {
		return ""
	}
	return sessDir
}

// sessionPhaseInfo holds the subset of session state needed for liveness checks.
type sessionPhaseInfo struct {
	Phase               string
	LastInteractionTime *time.Time
}

func readSessionPhaseInfo(sessDir, sessionID string) sessionPhaseInfo {
	data, err := os.ReadFile(filepath.Join(sessDir, sessionID+".json")) //nolint:gosec // sessDir is from git internals
	if err != nil {
		return sessionPhaseInfo{}
	}
	var partial struct {
		Phase               string     `json:"phase"`
		LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`
	}
	if json.Unmarshal(data, &partial) != nil {
		return sessionPhaseInfo{}
	}
	return sessionPhaseInfo{
		Phase:               partial.Phase,
		LastInteractionTime: partial.LastInteractionTime,
	}
}

// runWingmanApply is the entrypoint for the __apply subcommand, spawned by the
// stop hook when a pending REVIEW.md is detected. It re-checks preconditions
// and triggers claude --continue to apply the review.
func runWingmanApply(repoRoot string) error {
	wingmanLog("apply process started (pid=%d)", os.Getpid())

	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if !fileExists(reviewPath) {
		wingmanLog("no REVIEW.md found at %s, nothing to apply", reviewPath)
		return nil
	}
	wingmanLog("REVIEW.md found at %s", reviewPath)

	// Retry prevention: check if apply was already attempted for this review
	state := loadWingmanStateDirect(repoRoot)
	switch {
	case state == nil:
		wingmanLog("no wingman state found, proceeding without session check")
	case state.ApplyAttemptedAt != nil:
		wingmanLog("apply already attempted at %s, skipping", state.ApplyAttemptedAt.Format(time.RFC3339))
		return nil
	default:
		wingmanLog("wingman state loaded: session=%s", state.SessionID)
	}

	// Re-check session hasn't become active (user may have typed during spawn delay).
	// IDLE and ENDED are safe — only ACTIVE/ACTIVE_COMMITTED should block.
	if state != nil && state.SessionID != "" {
		sessDir := findSessionStateDir(repoRoot)
		if sessDir != "" {
			phaseInfo := readSessionPhaseInfo(sessDir, state.SessionID)
			if phaseInfo.Phase != "" && session.PhaseFromString(phaseInfo.Phase).IsActive() {
				wingmanLog("session is active (phase=%s), aborting (next stop hook will retry)", phaseInfo.Phase)
				return nil
			}
			wingmanLog("session phase=%s, safe to proceed", phaseInfo.Phase)
		}
	}

	// Mark apply as attempted BEFORE triggering
	if state != nil {
		now := time.Now()
		state.ApplyAttemptedAt = &now
		saveWingmanStateDirect(repoRoot, state)
	}

	wingmanLog("triggering auto-apply via claude --continue")
	applyStart := time.Now()
	if err := triggerAutoApply(repoRoot); err != nil {
		wingmanLog("ERROR auto-apply failed after %s: %v", time.Since(applyStart).Round(time.Millisecond), err)
		return fmt.Errorf("failed to trigger auto-apply: %w", err)
	}
	wingmanLog("auto-apply completed in %s", time.Since(applyStart).Round(time.Millisecond))

	return nil
}

// triggerAutoApply spawns claude --continue to apply the review suggestions.
// NOTE: This uses --continue which is Claude-specific and not part of the
// Prompter interface. If the wingman agent is not claude-code, auto-apply
// is skipped.
func triggerAutoApply(repoRoot string) error {
	agentName := resolveWingmanAgent()
	if agentName != agent.AgentNameClaudeCode {
		wingmanLog("auto-apply skipped: --continue is only supported for claude-code (agent=%s)", agentName)
		return nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), wingmanApplyTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "claude",
		"--continue",
		"--print",
		"--setting-sources", "",
		// Auto-accept edits so the agent can modify files and delete REVIEW.md
		// without requiring user consent (this runs in a background process).
		"--permission-mode", "acceptEdits",
		wingmanApplyInstruction,
	)
	cmd.Dir = repoRoot
	// Strip GIT_* env vars to prevent hook interference, and set
	// ENTIRE_WINGMAN_APPLY=1 so git hooks (post-commit) know not to
	// trigger another wingman review (prevents infinite recursion).
	env := agent.StripGitEnv(os.Environ())
	env = append(env, "ENTIRE_WINGMAN_APPLY=1")
	cmd.Env = env

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	return cmd.Run() //nolint:wrapcheck // caller wraps
}

// saveWingmanStateDirect writes the wingman state file directly to a known path
// under repoRoot, avoiding os.Chdir (which mutates process-wide state).
func saveWingmanStateDirect(repoRoot string, state *WingmanState) {
	statePath := filepath.Join(repoRoot, wingmanStateFile)
	if err := os.MkdirAll(filepath.Dir(statePath), 0o750); err != nil {
		return
	}
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return
	}
	//nolint:gosec,errcheck // G306: state file is config, not secrets; best-effort write
	_ = os.WriteFile(statePath, data, 0o644)
}

		},
	}
}

// triggerWingmanReview checks preconditions and spawns the detached review process.
func triggerWingmanReview(payload WingmanPayload) {
	// Prevent infinite recursion: if we're inside a wingman auto-apply,
	// don't trigger another review. The env var is set by triggerAutoApply.
	if os.Getenv("ENTIRE_WINGMAN_APPLY") != "" {
		return
	}

	logCtx := logging.WithComponent(context.Background(), "wingman")
	repoRoot := payload.RepoRoot

	totalFiles := len(payload.ModifiedFiles) + len(payload.NewFiles) + len(payload.DeletedFiles)
	logging.Info(logCtx, "wingman trigger evaluating",
		slog.String("session_id", payload.SessionID),
		slog.Int("file_count", totalFiles),
	)

	// Check if a pending REVIEW.md already exists for the current session
	if shouldSkipPendingReview(repoRoot, payload.SessionID) {
		logging.Info(logCtx, "wingman skipped: pending review exists for current session")
		fmt.Fprintf(os.Stderr, "[wingman] Pending review exists, skipping\n")
		return
	}

	// Atomic lock file prevents concurrent review spawns. O_CREATE|O_EXCL
	// is atomic on all platforms, avoiding the TOCTOU race of Stat+WriteFile.
	lockPath := filepath.Join(repoRoot, wingmanLockFile)
	if !acquireWingmanLock(lockPath, payload.SessionID) {
		logging.Info(logCtx, "wingman skipped: review already in progress")
		fmt.Fprintf(os.Stderr, "[wingman] Review in progress, skipping\n")
		return
	}

	// Dedup check: compute hash of sorted file paths
	allFiles := make([]string, 0, len(payload.ModifiedFiles)+len(payload.NewFiles)+len(payload.DeletedFiles))
	allFiles = append(allFiles, payload.ModifiedFiles...)
	allFiles = append(allFiles, payload.NewFiles...)
	allFiles = append(allFiles, payload.DeletedFiles...)
	filesHash := computeFilesHash(allFiles)

	state, _ := loadWingmanState() //nolint:errcheck // best-effort dedup
	if state != nil && state.FilesHash == filesHash && state.SessionID == payload.SessionID {
		logging.Info(logCtx, "wingman skipped: dedup hash match",
			slog.String("files_hash", filesHash[:12]),
		)
		fmt.Fprintf(os.Stderr, "[wingman] Already reviewed these changes, skipping\n")
		return
	}

	// Capture HEAD at trigger time so the detached review diffs against
	// the correct commit even if HEAD moves during the initial delay.
	payload.BaseCommit = resolveHEAD(repoRoot)
	logging.Debug(logCtx, "wingman captured base commit",
		slog.String("base_commit", payload.BaseCommit),
	)

	// Write payload to a temp file instead of passing as a CLI argument,
	// which can exceed OS argv limits (~128KB Linux, ~256KB macOS) with
	// many files or long prompts.
	payloadJSON, err := json.Marshal(payload)
	if err != nil {
		logging.Error(logCtx, "wingman failed to marshal payload", slog.Any("error", err))
		fmt.Fprintf(os.Stderr, "[wingman] Failed to marshal payload: %v\n", err)
		_ = os.Remove(lockPath)
		return
	}
	payloadPath := filepath.Join(repoRoot, ".entire", "wingman-payload.json")
	//nolint:gosec // G306: payload file is not secrets
	if err := os.WriteFile(payloadPath, payloadJSON, 0o644); err != nil {
		logging.Error(logCtx, "wingman failed to write payload file", slog.Any("error", err))
		fmt.Fprintf(os.Stderr, "[wingman] Failed to write payload file: %v\n", err)
		_ = os.Remove(lockPath)
		return
