	// wingmanStopHookReviewTimeout is how long the Stop hook will block
	// waiting for the background review to complete before falling back
	// to the existing UserPromptSubmit injection path.
	wingmanStopHookReviewTimeout = 90 * time.Second

	// wingmanReviewPollInterval is how often to check for REVIEW.md
	// while blocking in the Stop hook.
	wingmanReviewPollInterval = 2 * time.Second
)

