func TestIsWingmanEnabled_Settings(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		options  map[string]any
		expected bool
	}{
		{
			name:     "nil options",
			options:  nil,
			expected: false,
		},
		{
			name:     "empty options",
			options:  map[string]any{},
			expected: false,
		},
		{
			name:     "wingman not present",
			options:  map[string]any{"summarize": map[string]any{"enabled": true}},
			expected: false,
		},
		{
