func TestWaitForWingmanReview_Timeout(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()
	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o750); err != nil {
		t.Fatalf("failed to create .entire dir: %v", err)
	}

	// Create lock file but never write REVIEW.md or remove lock
	lockPath := filepath.Join(tmpDir, wingmanLockFile)
	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
		t.Fatalf("failed to create lock file: %v", err)
	}

	start := time.Now()
	result := waitForWingmanReview(tmpDir, 200*time.Millisecond)
	elapsed := time.Since(start)

	if result {
		t.Error("expected waitForWingmanReview to return false on timeout")
	}
	if elapsed < 200*time.Millisecond {
		t.Errorf("expected to wait at least 200ms, waited %v", elapsed)
	}
}

