	lockPath := filepath.Join(tmpDir, wingmanLockFile)
	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
		t.Fatalf("failed to create lock file: %v", err)
	}

	// Simulate review process: write REVIEW.md then remove lock (like runWingmanReview defer)
	go func() {
		time.Sleep(200 * time.Millisecond)
		reviewPath := filepath.Join(tmpDir, wingmanReviewFile)
		content := "# Review\n\n### [WARNING] Potential issue\n\nSomething needs attention."
		if err := os.WriteFile(reviewPath, []byte(content), 0o644); err != nil {
			panic(fmt.Sprintf("test setup: failed to write REVIEW.md: %v", err))
		}
		// Lock removed after write (matches runWingmanReview defer order)
		_ = os.Remove(lockPath)
	}()

	result := waitForWingmanReview(tmpDir, 5*time.Second)
	if !result {
		t.Error("expected waitForWingmanReview to return true when review has actionable issues")
	}
}

