			name:     "wingman wrong type",
			options:  map[string]any{"wingman": "invalid"},
			expected: false,
		},
		{
			name:     "wingman enabled wrong type",
			options:  map[string]any{"wingman": map[string]any{"enabled": "yes"}},
			expected: false,
		},
	}

