+func TestWaitForWingmanReview_ReviewAppears(t *testing.T) {
+	t.Parallel()
+
+	tmpDir := t.TempDir()
+	entireDir := filepath.Join(tmpDir, ".entire")
+	if err := os.MkdirAll(entireDir, 0o750); err != nil {
+		t.Fatalf("failed to create .entire dir: %v", err)
+	}
+
+	// Create the lock file (review in progress)
+	lockPath := filepath.Join(tmpDir, wingmanLockFile)
+	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
+		t.Fatalf("failed to create lock file: %v", err)
+	}
+
+	// Simulate review process: write REVIEW.md then remove lock (like runWingmanReview defer)
+	go func() {
+		time.Sleep(200 * time.Millisecond)
+		reviewPath := filepath.Join(tmpDir, wingmanReviewFile)
+		content := "# Review\n\n### [WARNING] Potential issue\n\nSomething needs attention."
+		if err := os.WriteFile(reviewPath, []byte(content), 0o644); err != nil {
+			panic(fmt.Sprintf("test setup: failed to write REVIEW.md: %v", err))
+		}
+		// Lock removed after write (matches runWingmanReview defer order)
+		_ = os.Remove(lockPath)
+	}()
+
+	result := waitForWingmanReview(tmpDir, 5*time.Second)
+	if !result {
+		t.Error("expected waitForWingmanReview to return true when review has actionable issues")
+	}
+}
+
+func TestWaitForWingmanReview_NoActionableIssues(t *testing.T) {
+	t.Parallel()
+
+	tmpDir := t.TempDir()
+	entireDir := filepath.Join(tmpDir, ".entire")
+	if err := os.MkdirAll(entireDir, 0o750); err != nil {
+		t.Fatalf("failed to create .entire dir: %v", err)
+	}
+
+	// Create the lock file
+	lockPath := filepath.Join(tmpDir, wingmanLockFile)
+	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
+		t.Fatalf("failed to create lock file: %v", err)
+	}
+
+	// Simulate review: write REVIEW.md without severity markers, then remove lock
+	go func() {
+		time.Sleep(200 * time.Millisecond)
+		reviewPath := filepath.Join(tmpDir, wingmanReviewFile)
+		content := "# Review\n\nEverything looks good!"
+		if err := os.WriteFile(reviewPath, []byte(content), 0o644); err != nil {
+			panic(fmt.Sprintf("test setup: failed to write REVIEW.md: %v", err))
+		}
+		_ = os.Remove(lockPath)
+	}()
+
+	result := waitForWingmanReview(tmpDir, 5*time.Second)
+	if result {
+		t.Error("expected waitForWingmanReview to return false when no actionable issues")
+	}
+
+	// Verify REVIEW.md was cleaned up
+	reviewPath := filepath.Join(tmpDir, wingmanReviewFile)
+	if _, err := os.Stat(reviewPath); err == nil {
+		t.Error("expected REVIEW.md to be cleaned up when no actionable issues")
+	}
+}
+
+func TestWaitForWingmanReview_LockRemoved(t *testing.T) {
+	t.Parallel()
+
+	tmpDir := t.TempDir()
+	entireDir := filepath.Join(tmpDir, ".entire")
+	if err := os.MkdirAll(entireDir, 0o750); err != nil {
+		t.Fatalf("failed to create .entire dir: %v", err)
+	}
+
+	// Create the lock file
+	lockPath := filepath.Join(tmpDir, wingmanLockFile)
+	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
+		t.Fatalf("failed to create lock file: %v", err)
+	}
+
+	// Remove lock without writing REVIEW.md (simulates review finding no changes)
+	go func() {
+		time.Sleep(200 * time.Millisecond)
+		_ = os.Remove(lockPath)
+	}()
+
+	result := waitForWingmanReview(tmpDir, 5*time.Second)
+	if result {
+		t.Error("expected waitForWingmanReview to return false when lock removed without REVIEW.md")
+	}
+}
+
+func TestWaitForWingmanReview_Timeout(t *testing.T) {
+	t.Parallel()
+
+	tmpDir := t.TempDir()
+	entireDir := filepath.Join(tmpDir, ".entire")
+	if err := os.MkdirAll(entireDir, 0o750); err != nil {
+		t.Fatalf("failed to create .entire dir: %v", err)
+	}
+
+	// Create lock file but never write REVIEW.md or remove lock
+	lockPath := filepath.Join(tmpDir, wingmanLockFile)
+	if err := os.WriteFile(lockPath, []byte("test"), 0o644); err != nil {
+		t.Fatalf("failed to create lock file: %v", err)
+	}
+
+	start := time.Now()
+	result := waitForWingmanReview(tmpDir, 200*time.Millisecond)
+	elapsed := time.Since(start)
+
+	if result {
+		t.Error("expected waitForWingmanReview to return false on timeout")
+	}
+	if elapsed < 200*time.Millisecond {
+		t.Errorf("expected to wait at least 200ms, waited %v", elapsed)
+	}
+}

