	}

	content := string(data)

	// The review format uses "### [SEVERITY] description" for each issue.
	// Check for any of the severity markers in heading context.
	for _, marker := range []string{"[CRITICAL]", "[WARNING]", "[SUGGESTION]"} {
		if strings.Contains(content, marker) {
			return true
		}
	}

	return false
}

// outputWingmanStopNotification outputs a systemMessage notification about
// wingman status at the end of a stop hook. This makes wingman activity visible
// in the agent terminal without injecting context into the agent's conversation.
// Best-effort: status may be stale due to concurrent wingman processes.
func outputWingmanStopNotification(repoRoot string) {
	if !settings.IsWingmanEnabled() {
		return
	}
	if os.Getenv("ENTIRE_WINGMAN_APPLY") != "" {
		return
	}

	lockPath := filepath.Join(repoRoot, wingmanLockFile)
	if info, err := os.Stat(lockPath); err == nil && time.Since(info.ModTime()) <= wingmanNotificationLockThreshold {
		_ = outputHookMessage("[Wingman] Reviewing your changes...") //nolint:errcheck // best-effort notification
		return
	}

	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if _, err := os.Stat(reviewPath); err == nil && reviewHasActionableIssues(reviewPath) {
		_ = outputHookMessage("[Wingman] Review pending \u2014 will be addressed on your next prompt") //nolint:errcheck // best-effort notification
		return
	}
}

// waitForWingmanReview polls for the review to complete by watching for the
// lock file to be removed. Returns true if the review completed with
// actionable issues, false if it timed out, had no issues, or the review
// process ended without producing a review.
//
// Safety: REVIEW.md is only read AFTER the lock file is gone. The review
// process (runWingmanReview) removes the lock in a defer that runs after
// WriteFile completes, so "lock gone + REVIEW.md exists" guarantees a
// fully-written file. Reading REVIEW.md while the lock is held could catch
// a partial write (os.WriteFile truncates then writes).
func waitForWingmanReview(repoRoot string, timeout time.Duration) bool {
	logCtx := logging.WithComponent(context.Background(), "wingman")
	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	lockPath := filepath.Join(repoRoot, wingmanLockFile)
	deadline := time.Now().Add(timeout)
	lastProgress := time.Now()

	for time.Now().Before(deadline) {
		// Only check REVIEW.md after the lock is gone (write is complete).
		if _, err := os.Stat(lockPath); err != nil {
			// Lock removed — review process has finished.
			if _, statErr := os.Stat(reviewPath); statErr == nil {
				if reviewHasActionableIssues(reviewPath) {
					logging.Info(logCtx, "review completed with actionable issues")
					return true
				}
				// Review exists but no actionable issues — clean up
				logging.Info(logCtx, "review completed with no actionable issues, cleaning up")
				_ = os.Remove(reviewPath)
				return false
			}
			// Lock gone, no REVIEW.md — review found no changes or failed
			logging.Info(logCtx, "lock file removed, review process ended without REVIEW.md")
			return false
		}

		// Periodic progress feedback (every 15s) so the user knows we're still alive
		if time.Since(lastProgress) >= 15*time.Second {
			fmt.Fprintf(os.Stderr, "[wingman] Still waiting for review...\n")
			lastProgress = time.Now()
		}

		time.Sleep(wingmanReviewPollInterval)
	}

	logging.Info(logCtx, "timed out waiting for wingman review",
		slog.Duration("timeout", timeout),
	)
	return false
}

